// Entrada
const p = $json.payload ?? $json;

if (!p?.project_id || !p?.chat_id) {
  const e = new Error('Policy Get: payload sem project_id/chat_id.');
  e.statusCode = 400;
  throw e;
}

const key = `${p.project_id}:${p.chat_id}`;

// 💡 Nó Code: use $getWorkflowStaticData
const store = $getWorkflowStaticData('global');

// cria estrutura, se não existir
store.chat_policies = store.chat_policies ?? {};

const row = store.chat_policies[key] ?? null;

return [{
  json: {
    payload: p,
    policy: row // ex.: { ia_disabled:true, assumed_by:'...', ... } ou null
  }
}];

const payload = $json.payload;
const policy  = $json.policy ?? null;

const ALLOWED_STEPS = new Set([
  'pré-venda',
  'qualificação',
  'medição',
  'montagem'
]);

const step = payload.project_step ?? null;
const stepAllowed = step ? ALLOWED_STEPS.has(step) : false;
const iaDisabled  = Boolean(policy?.ia_disabled === true);
const iaActive    = stepAllowed && !iaDisabled;

return [{
  json: {
    payload,
    context: {
      project_id: payload.project_id,
      chat_id: payload.chat_id,
      channel: payload.channel ?? null,
      project_step: step,
      step_allowed: stepAllowed,
      ia_disabled: iaDisabled,
      ia_active: iaActive,
      store_id: policy?.store_id ?? null,
      assumed_by: policy?.assumed_by ?? null,
      assumed_at: policy?.assumed_at ?? null
    }
  }
}];

const p = $json.payload ?? $json;

if (!p?.project_id || !p?.chat_id) {
  const e = new Error('Assumed: payload sem project_id/chat_id.');
  e.statusCode = 400;
  throw e;
}

const key = `${p.project_id}:${p.chat_id}`;

let store;
try {
  store = $getWorkflowStaticData('global');     // ✅ Code node
} catch (err) {
  store = global.__fakeStaticStore ??= {};
}

store.chat_policies = store.chat_policies ?? {};

const assumedAt = p.timestamp ?? new Date().toISOString();

store.chat_policies[key] = {
  ...(store.chat_policies[key] ?? {}),
  ia_disabled: true,
  assumed_by: p.agent_id ?? null,
  assumed_at: assumedAt,
  store_id: p.store_id ?? null,
  project_step: p.project_step ?? null,
  chat_status: p.chat_status ?? null,
  last_event: 'chat.agent_assumed',
};

return [{
  json: {
    ok: true,
    key,
    policy: store.chat_policies[key],
  }
}];

const out = $json;
console.log('CHAT ASSUMIDO:', JSON.stringify(out, null, 2));
return [{ json: { logged: true, ...out } }];

const REMOVE_ON_RELEASE = false; // ← mude para true se quiser remover a chave ao liberar

const p = $json.payload ?? $json;

// valida mínimos
if (!p?.project_id || !p?.chat_id) {
  const e = new Error('Release: payload sem project_id/chat_id.');
  e.statusCode = 400;
  throw e;
}

const key = `${p.project_id}:${p.chat_id}`;

// Obtém Static Data de forma compatível com nó Code.
// Em execução real (workflow ativado), $getWorkflowStaticData funciona.
// Em teste manual, usamos um fallback in-memory (não persiste).
let store;
try {
  store = $getWorkflowStaticData('global');  // ✅ Code node
} catch (err) {
  store = global.__fakeStaticStore ??= {};   // Fallback só p/ teste manual
}

store.chat_policies = store.chat_policies ?? {};

if (REMOVE_ON_RELEASE) {
  // Remoção total do registro
  const existed = Object.prototype.hasOwnProperty.call(store.chat_policies, key);
  delete store.chat_policies[key];

  return [{
    json: {
      ok: true,
      key,
      deleted: existed,
      last_event: 'chat.agent_released',
    }
  }];
} else {
  // Reativação mantendo histórico
  const existing = store.chat_policies[key] ?? {};
  const releasedAt = p.timestamp ?? new Date().toISOString();

  store.chat_policies[key] = {
    ...existing,
    ia_disabled: false,
    released_at: releasedAt,
    released_by: p.agent_id ?? null,
    // campos contextuais opcionais — atualiza se chegarem
    store_id: p.store_id ?? existing.store_id ?? null,
    project_step: p.project_step ?? existing.project_step ?? null,
    chat_status: p.chat_status ?? existing.chat_status ?? null,
    last_event: 'chat.agent_released',
  };

  return [{
    json: {
      ok: true,
      key,
      policy: store.chat_policies[key],
    }
  }];
}

const out = $json;
console.log('CHAT LIBERADO:', JSON.stringify(out, null, 2));
return [{ json: { logged: true, ...out } }];

const p = $json.payload ?? $json;
const unsupportedType = p?.message?.type ?? 'unknown';

return [{
  json: {
    project_id: p.project_id,
    chat_id: p.chat_id,
    ia_user_id: p.ia_user_id,
    event_id: p.event_id,
    original_type: unsupportedType,
    note: `Mensagem com tipo não suportado: "${unsupportedType}". Evento registrado pelo fallback do n8n.`,
    metadata: {
      channel: p.channel,
      timestamp: p.timestamp,
      message_id: p.message?.id ?? null
    }
  }
}];

const p = $json.payload ?? $json;

// Segurança extra, caso o Switch seja bypassado por engano
if (!p?.message || p.message.type !== 'text') {
  const err = new Error(`Extrair Texto: tipo inválido (${p?.message?.type ?? 'desconhecido'}).`);
  err.statusCode = 400;
  throw err;
}

// --------- Sanitização ---------
const RAW = String(p.message.text ?? '');

// normaliza quebras de linha e espaços invisíveis (NBSP, ZWSP)
let cleaned = RAW
  .replace(/\r\n?/g, '\n')        // \r\n -> \n
  .replace(/\u00A0/g, ' ')        // NBSP -> espaço
  .replace(/[\u200B-\u200D]/g, '')// zero-width spaces
  .replace(/\s+\n/g, '\n')        // espaços antes de \n
  .replace(/\n{3,}/g, '\n\n')     // compacta múltiplas linhas vazias
  .trim();

// --------- Limite de tamanho ---------
const MAX_CHARS = 4000; // ajuste se quiser
const truncated = cleaned.length > MAX_CHARS;
const text = truncated ? cleaned.slice(0, MAX_CHARS) : cleaned;

// --------- Extra: URLs ---------
const urlRegex = /\bhttps?:\/\/[^\s<>"'`]+/gi;
const urls = text.match(urlRegex) ?? [];

// --------- Monta saída padronizada ---------
return [{
  json: {
    context: {
      event_id: p.event_id,
      timestamp: p.timestamp,
      project_id: p.project_id,
      chat_id: p.chat_id,
      channel: p.channel,
      ia_user_id: p.ia_user_id,
      customer_phone: p.customer?.phone ?? null,
      customer_name: p.customer?.name ?? null
    },
    message: {
      id: p.message.id,
      type: 'text',
      direction: p.message.direction,
      text,
      length: text.length,
      truncated,
      urls
    },
    meta: {
      original_length: cleaned.length,
      had_urls: urls.length > 0,
      received_at: p.received_at ?? new Date().toISOString()
    }
  }
}];

const p = $json.payload ?? $json;

// Segurança extra: garante que veio pelo output correto do Switch
if (!p?.message || p.message.type !== 'image') {
  const err = new Error(`Extrair Imagem: tipo inválido (${p?.message?.type ?? 'desconhecido'}).`);
  err.statusCode = 400;
  throw err;
}

const attachments = Array.isArray(p.message.attachments) ? p.message.attachments : [];
if (!attachments.length) {
  const err = new Error('Extrair Imagem: attachments ausentes para message.type = image.');
  err.statusCode = 400;
  throw err;
}

// Mime-types aceitos (ajuste se necessário)
const ALLOWED = new Set(['image/jpeg','image/png','image/webp','image/heic','image/heif']);

// sanitizador simples de textos (caption)
const sanitizeText = (s) => String(s ?? '')
  .replace(/\r\n?/g, '\n')
  .replace(/\u00A0/g, ' ')        // NBSP
  .replace(/[\u200B-\u200D]/g, '')// zero-width
  .replace(/\s+\n/g, '\n')
  .replace(/\n{3,}/g, '\n\n')
  .trim();

// util para deduzir extensão
const extFromMime = (mime) => {
  if (!mime) return null;
  const map = {
    'image/jpeg': 'jpg',
    'image/png': 'png',
    'image/webp': 'webp',
    'image/heic': 'heic',
    'image/heif': 'heif',
  };
  return map[mime.toLowerCase()] ?? null;
};

// Se quiser processar apenas a primeira imagem, use [0].
// Se quiser permitir várias, fazemos map e retornamos todas.
const images = attachments.map((att, idx) => {
  if (!att || typeof att !== 'object') {
    throw Object.assign(new Error(`Attachment inválido em attachments[${idx}]`), { statusCode: 400 });
  }

  const url = String(att.url ?? '').trim();
  const mime = String(att.mime_type ?? '').trim().toLowerCase();

  if (!url) {
    throw Object.assign(new Error(`attachments[${idx}].url é obrigatório.`), { statusCode: 400 });
  }
  if (!mime) {
    throw Object.assign(new Error(`attachments[${idx}].mime_type é obrigatório.`), { statusCode: 400 });
  }
  // Validação de mime (pode relaxar se necessário)
  if (!ALLOWED.has(mime)) {
    throw Object.assign(new Error(`Mime-type não suportado: ${mime}`), { statusCode: 415 });
  }

  const filename = att.filename ? String(att.filename) : null;
  const ext = filename?.includes('.') ? filename.split('.').pop() : extFromMime(mime);
  const caption = sanitizeText(att.caption);

  // metadados auxiliares
  const sizeBytes = (typeof att.size_bytes === 'number' && att.size_bytes >= 0) ? att.size_bytes : null;
  const sha256 = att.sha256 ? String(att.sha256) : null;

  return {
    url,
    mime_type: mime,
    filename: filename ?? (ext ? `image_${idx}.${ext}` : `image_${idx}`),
    extension: ext,
    caption: caption || null,
    size_bytes: sizeBytes,
    sha256,
    index: idx
  };
});

// Monta saída padronizada
return [{
  json: {
    context: {
      event_id: p.event_id,
      timestamp: p.timestamp,
      project_id: p.project_id,
      chat_id: p.chat_id,
      channel: p.channel,
      ia_user_id: p.ia_user_id,
      customer_phone: p.customer?.phone ?? null,
      customer_name: p.customer?.name ?? null
    },
    message: {
      id: p.message.id,
      type: 'image',
      direction: p.message.direction,
      // Se quiser só a primeira imagem nos próximos nós, pegue images[0]
      images, // array com 1..N imagens
      count: images.length
    },
    meta: {
      received_at: p.received_at ?? new Date().toISOString(),
      allowed_mimes: Array.from(ALLOWED)
    }
  }
}];

const p = $json.payload ?? $json;

// Segurança extra: garante que veio pelo output correto do Switch
if (!p?.message || p.message.type !== 'audio') {
  const err = new Error(`Extrair Áudio: tipo inválido (${p?.message?.type ?? 'desconhecido'}).`);
  err.statusCode = 400;
  throw err;
}

const attachments = Array.isArray(p.message.attachments) ? p.message.attachments : [];
if (!attachments.length) {
  const err = new Error('Extrair Áudio: attachments ausentes para message.type = audio.');
  err.statusCode = 400;
  throw err;
}

// Lista de mime-types aceitos (ajuste conforme suporte do seu pipeline de STT)
const ALLOWED = new Set([
  'audio/ogg',     // WhatsApp (opus) costuma vir como "audio/ogg; codecs=opus"
  'audio/mpeg',    // mp3
  'audio/mp3',     // variação
  'audio/webm',    // webm/opus
  'audio/aac',
  'audio/wav',
  'audio/x-wav',
  'audio/opus'
]);

// Limites opcionais
const MAX_SIZE_BYTES = 25 * 1024 * 1024; // 25 MB (ajuste se necessário)
const MAX_DURATION_SEC = 15 * 60;        // 15 min (ajuste se necessário)

// util: normaliza mime removendo sufixos "; codecs=..."
// e espaços
const normalizeMime = (m) => {
  if (!m) return '';
  return String(m).toLowerCase().split(';')[0].trim();
};

// util: tenta deduzir extensão do mime
const extFromMime = (mime) => {
  const map = {
    'audio/ogg': 'ogg',
    'audio/mpeg': 'mp3',
    'audio/mp3': 'mp3',
    'audio/webm': 'webm',
    'audio/aac': 'aac',
    'audio/wav': 'wav',
    'audio/x-wav': 'wav',
    'audio/opus': 'opus'
  };
  return map[mime] ?? null;
};

// Se quiser processar vários áudios, usamos map; se espera 1, pegaremos [0] adiante.
const audios = attachments.map((att, idx) => {
  if (!att || typeof att !== 'object') {
    throw Object.assign(new Error(`Attachment inválido em attachments[${idx}]`), { statusCode: 400 });
  }

  const url = String(att.url ?? '').trim();
  if (!url) {
    throw Object.assign(new Error(`attachments[${idx}].url é obrigatório.`), { statusCode: 400 });
  }

  const rawMime = String(att.mime_type ?? '').trim();
  const mime = normalizeMime(rawMime);
  if (!mime) {
    throw Object.assign(new Error(`attachments[${idx}].mime_type é obrigatório.`), { statusCode: 400 });
  }
  if (!ALLOWED.has(mime)) {
    throw Object.assign(new Error(`Mime-type não suportado: ${rawMime}`), { statusCode: 415 });
  }

  // metadados opcionais (se o CLIENT_APP enviar)
  const sizeBytes = (typeof att.size_bytes === 'number' && att.size_bytes >= 0) ? att.size_bytes : null;
  const durationSec = (typeof att.duration_seconds === 'number' && att.duration_seconds >= 0) ? att.duration_seconds : null;
  const sha256 = att.sha256 ? String(att.sha256) : null;

  // valida limites, se existirem
  if (sizeBytes !== null && sizeBytes > MAX_SIZE_BYTES) {
    throw Object.assign(new Error(`Arquivo de áudio excede o limite (${sizeBytes} > ${MAX_SIZE_BYTES} bytes).`), { statusCode: 413 });
  }
  if (durationSec !== null && durationSec > MAX_DURATION_SEC) {
    throw Object.assign(new Error(`Duração de áudio excede o limite (${durationSec}s > ${MAX_DURATION_SEC}s).`), { statusCode: 413 });
  }

  const filename = att.filename ? String(att.filename) : null;
  const ext = filename?.includes('.') ? filename.split('.').pop() : extFromMime(mime);

  return {
    url,
    mime_type: mime,          // já normalizado
    mime_type_raw: rawMime,   // como veio
    filename: filename ?? (ext ? `audio_${idx}.${ext}` : `audio_${idx}`),
    extension: ext,
    size_bytes: sizeBytes,
    duration_seconds: durationSec,
    sha256,
    index: idx
  };
});

// Saída padronizada
return [{
  json: {
    context: {
      event_id: p.event_id,
      timestamp: p.timestamp,
      project_id: p.project_id,
      chat_id: p.chat_id,
      channel: p.channel,
      ia_user_id: p.ia_user_id,
      customer_phone: p.customer?.phone ?? null,
      customer_name: p.customer?.name ?? null
    },
    message: {
      id: p.message.id,
      type: 'audio',
      direction: p.message.direction,
      audios,     // array com 1..N itens
      count: audios.length
    },
    meta: {
      received_at: p.received_at ?? new Date().toISOString(),
