  if (!ALLOWED.has(mime)) {
    throw Object.assign(new Error(`Mime-type não suportado: ${rawMime}`), { statusCode: 415 });
  }

  // metadados opcionais (se o CLIENT_APP enviar)
  const sizeBytes = (typeof att.size_bytes === 'number' && att.size_bytes >= 0) ? att.size_bytes : null;
  const durationSec = (typeof att.duration_seconds === 'number' && att.duration_seconds >= 0) ? att.duration_seconds : null;
  const sha256 = att.sha256 ? String(att.sha256) : null;

  // valida limites, se existirem
  if (sizeBytes !== null && sizeBytes > MAX_SIZE_BYTES) {
    throw Object.assign(new Error(`Arquivo de áudio excede o limite (${sizeBytes} > ${MAX_SIZE_BYTES} bytes).`), { statusCode: 413 });
  }
  if (durationSec !== null && durationSec > MAX_DURATION_SEC) {
    throw Object.assign(new Error(`Duração de áudio excede o limite (${durationSec}s > ${MAX_DURATION_SEC}s).`), { statusCode: 413 });
  }

  const filename = att.filename ? String(att.filename) : null;
  const ext = filename?.includes('.') ? filename.split('.').pop() : extFromMime(mime);

  return {
    url,
    mime_type: mime,          // já normalizado
    mime_type_raw: rawMime,   // como veio
    filename: filename ?? (ext ? `audio_${idx}.${ext}` : `audio_${idx}`),
    extension: ext,
    size_bytes: sizeBytes,
    duration_seconds: durationSec,
    sha256,
    index: idx
  };
});

// Saída padronizada
return [{
  json: {
    context: {
      event_id: p.event_id,
      timestamp: p.timestamp,
      project_id: p.project_id,
      chat_id: p.chat_id,
      channel: p.channel,
      ia_user_id: p.ia_user_id,
      customer_phone: p.customer?.phone ?? null,
      customer_name: p.customer?.name ?? null
    },
    message: {
      id: p.message.id,
      type: 'audio',
      direction: p.message.direction,
      audios,     // array com 1..N itens
      count: audios.length
    },
    meta: {
      received_at: p.received_at ?? new Date().toISOString(),
      allowed_mimes: Array.from(ALLOWED),
      max_size_bytes: MAX_SIZE_BYTES,
      max_duration_seconds: MAX_DURATION_SEC
    }
  }
}];

const p = $json.payload ?? $json;
const t = p?.message?.type;

const SUPPORTED = new Set(['document','video','location','contact','sticker','template']);
if (!p?.message || !SUPPORTED.has(t)) {
  const err = new Error(`Extrair Mídia (Genérico): tipo inválido (${t ?? 'desconhecido'}).`);
  err.statusCode = 400;
  throw err;
}

const asArray = (v) => Array.isArray(v) ? v : [];
const attachments = asArray(p.message.attachments);

// ---- helpers ----
const normalizeMime = (m) => String(m || '').toLowerCase().split(';')[0].trim();

const extFromMime = (mime, map) => map[mime] ?? null;

const sanitizeText = (s) => String(s ?? '')
  .replace(/\r\n?/g, '\n')
  .replace(/\u00A0/g, ' ')
  .replace(/[\u200B-\u200D]/g, '')
  .replace(/\s+\n/g, '\n')
  .replace(/\n{3,}/g, '\n\n')
  .trim();

// limites opcionais
const LIMITS = {
  document: { maxBytes: 50 * 1024 * 1024 }, // 50MB
  video:    { maxBytes: 100 * 1024 * 1024 } // 100MB
};

// mimes aceitos
const MIME_MAP_DOC = {
  'application/pdf': 'pdf',
  'application/msword': 'doc',
  'application/vnd.openxmlformats-officedocument.wordprocessingml.document': 'docx',
  'application/vnd.ms-excel': 'xls',
  'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet': 'xlsx',
  'application/vnd.ms-powerpoint': 'ppt',
  'application/vnd.openxmlformats-officedocument.presentationml.presentation': 'pptx',
  'text/plain': 'txt',
  'application/zip': 'zip',
  'application/x-zip-compressed': 'zip'
};
const MIME_MAP_VIDEO = {
  'video/mp4': 'mp4',
  'video/webm': 'webm',
  'video/3gpp': '3gp',
  'video/quicktime': 'mov',
};
const MIME_STICKER = new Set(['image/webp','image/png']); // WA stickers geralmente webp

const ALLOWED_DOC = new Set(Object.keys(MIME_MAP_DOC));
const ALLOWED_VIDEO = new Set(Object.keys(MIME_MAP_VIDEO));

// ---- builders por tipo ----
const buildFromAttachments = (allowedSet, mimeMap, kind) => {
  if (!attachments.length) {
    const e = new Error(`attachments ausentes para message.type = ${kind}.`);
    e.statusCode = 400; throw e;
  }
  return attachments.map((att, idx) => {
    if (!att || typeof att !== 'object') {
      throw Object.assign(new Error(`Attachment inválido em attachments[${idx}]`), { statusCode: 400 });
    }
    const url = String(att.url ?? '').trim();
    const rawMime = String(att.mime_type ?? '').trim();
    const mime = normalizeMime(rawMime);
    if (!url)  throw Object.assign(new Error(`attachments[${idx}].url é obrigatório.`),  { statusCode: 400 });
    if (!mime) throw Object.assign(new Error(`attachments[${idx}].mime_type é obrigatório.`), { statusCode: 400 });

    if (kind === 'document' && !allowedSet.has(mime)) {
      throw Object.assign(new Error(`Documento com mime não suportado: ${rawMime}`), { statusCode: 415 });
    }
    if (kind === 'video' && !allowedSet.has(mime)) {
      throw Object.assign(new Error(`Vídeo com mime não suportado: ${rawMime}`), { statusCode: 415 });
    }
    if (kind === 'sticker' && !MIME_STICKER.has(mime)) {
      throw Object.assign(new Error(`Sticker com mime não suportado: ${rawMime}`), { statusCode: 415 });
    }

    const size = (typeof att.size_bytes === 'number' && att.size_bytes >= 0) ? att.size_bytes : null;
    if (size !== null && LIMITS[kind]?.maxBytes && size > LIMITS[kind].maxBytes) {
      throw Object.assign(new Error(`${kind} excede o tamanho máximo (${size} > ${LIMITS[kind].maxBytes} bytes).`), { statusCode: 413 });
    }

    const filename = att.filename ? String(att.filename) : null;
    const ext = filename?.includes('.') ? filename.split('.').pop()
               : (kind === 'document' ? extFromMime(mime, MIME_MAP_DOC)
                 : kind === 'video'   ? extFromMime(mime, MIME_MAP_VIDEO)
                 : mime === 'image/webp' ? 'webp'
                 : mime === 'image/png'  ? 'png' : null);

    const entry = {
      url,
      mime_type: mime,
      mime_type_raw: rawMime,
      filename: filename ?? `${kind}_${idx}${ext ? '.'+ext : ''}`,
      extension: ext,
      size_bytes: size,
      sha256: att.sha256 ? String(att.sha256) : null,
      index: idx
    };

    // campos específicos
    if (kind === 'video') {
      entry.duration_seconds = (typeof att.duration_seconds === 'number' && att.duration_seconds >= 0) ? att.duration_seconds : null;
      entry.caption = sanitizeText(att.caption) || null;
    }
    if (kind === 'document') {
      entry.caption = sanitizeText(att.caption) || null;
      entry.pages = (typeof att.pages === 'number' && att.pages > 0) ? att.pages : null;
    }
    if (kind === 'sticker') {
      entry.is_animated = Boolean(att.animated ?? false);
    }

    return entry;
  });
};

let outMessage;

// ------- switch por tipo -------
switch (t) {
  case 'document': {
    const documents = buildFromAttachments(ALLOWED_DOC, MIME_MAP_DOC, 'document');
    outMessage = { id: p.message.id, type: 'document', direction: p.message.direction, documents, count: documents.length };
    break;
  }
  case 'video': {
    const videos = buildFromAttachments(ALLOWED_VIDEO, MIME_MAP_VIDEO, 'video');
    outMessage = { id: p.message.id, type: 'video', direction: p.message.direction, videos, count: videos.length };
    break;
  }
  case 'sticker': {
    const stickers = buildFromAttachments(null, null, 'sticker');
    outMessage = { id: p.message.id, type: 'sticker', direction: p.message.direction, stickers, count: stickers.length };
    break;
  }
  case 'location': {
    const loc = p.message.location || {};
    const lat = Number(loc.latitude), lng = Number(loc.longitude);
    if (!isFinite(lat) || !isFinite(lng)) {
      const e = new Error('location.latitude e location.longitude são obrigatórios e numéricos.');
      e.statusCode = 400; throw e;
    }
    outMessage = {
      id: p.message.id, type: 'location', direction: p.message.direction,
      location: {
        latitude: lat,
        longitude: lng,
        address: sanitizeText(loc.address) || null,
        name: sanitizeText(loc.name) || null
      }
    };
    break;
  }
  case 'contact': {
    const contacts = asArray(p.message.contacts).map((c, idx) => {
      if (!c || typeof c !== 'object') {
        throw Object.assign(new Error(`contacts[${idx}] inválido`), { statusCode: 400 });
      }
      const phone = String(c.phone ?? '').trim();
      const name  = sanitizeText(c.name);
      if (!phone) {
        throw Object.assign(new Error(`contacts[${idx}].phone é obrigatório`), { statusCode: 400 });
      }
      return {
        phone,
        name: name || null,
        org: sanitizeText(c.org) || null,
        vcard: c.vcard ? String(c.vcard) : null,
        index: idx
      };
    });
    if (!contacts.length) {
      const e = new Error('contacts ausente/vazio para message.type = contact.');
      e.statusCode = 400; throw e;
    }
    outMessage = { id: p.message.id, type: 'contact', direction: p.message.direction, contacts, count: contacts.length };
    break;
  }
  case 'template': {
    const tpl = p.message.template || {};
    const name = String(tpl.name ?? '').trim();
    if (!name) { const e = new Error('template.name é obrigatório.'); e.statusCode = 400; throw e; }
    outMessage = {
      id: p.message.id, type: 'template', direction: p.message.direction,
      template: {
        name,
        namespace: tpl.namespace ?? null,
        language: tpl.language ?? null,
        components: Array.isArray(tpl.components) ? tpl.components : null
      }
    };
    break;
  }
}

// ---- saída padronizada ----
return [{
  json: {
    context: {
      event_id: p.event_id,
      timestamp: p.timestamp,
      project_id: p.project_id,
      chat_id: p.chat_id,
      channel: p.channel,
      ia_user_id: p.ia_user_id,
      customer_phone: p.customer?.phone ?? null,
      customer_name: p.customer?.name ?? null
    },
    message: outMessage,
    meta: {
      received_at: p.received_at ?? new Date().toISOString(),
      limits: LIMITS,
      allowed_doc_mimes: Array.from(ALLOWED_DOC),
      allowed_video_mimes: Array.from(ALLOWED_VIDEO),
      allowed_sticker_mimes: Array.from(MIME_STICKER)
    }
  }
}];

const ctx = $json.context ?? {};
const msg = $json.message ?? {};

const ensure = (cond, message, statusCode = 400) => {
  if (!cond) {
    const e = new Error(message); e.statusCode = statusCode; throw e;
  }
};

// Campos básicos vindos do contexto
const chat_id    = ctx.chat_id    ?? null;
const project_id = ctx.project_id ?? null;
const timestamp  = ctx.timestamp  ?? new Date().toISOString();
const user_id    = ctx.customer_phone ?? null; // usamos o phone como id de usuário final
const user_name  = ctx.customer_name ?? null;

ensure(chat_id && project_id, 'Unificar: context.chat_id e context.project_id são obrigatórios.');
ensure(msg && typeof msg === 'object', 'Unificar: message ausente.');

// Mapeia por tipo
const type = msg.type;
ensure(typeof type === 'string', 'Unificar: message.type ausente.');

let message_content = null;   // texto ou conteúdo primário
let caption = null;
let attachments = [];         // lista genérica (url/mime/filename/size/sha256/..)
let duration_seconds = null;  // para áudio/vídeo
let location = null;          // para location
let contacts = null;          // para contact
let template = null;          // para template
let direction = msg.direction ?? 'inbound';

// Normaliza por tipo
switch (type) {
  case 'text': {
    ensure(typeof msg.text === 'string', 'Unificar: message.text obrigatório para type=text.');
    message_content = msg.text;
    break;
  }
  case 'image': {
    const images = Array.isArray(msg.images) ? msg.images : [];
    ensure(images.length > 0, 'Unificar: images vazio para type=image.');
    message_content = images[0].url;
    caption = images[0].caption ?? null;
    attachments = images.map(i => ({
      kind: 'image',
      url: i.url,
      mime_type: i.mime_type,
      filename: i.filename,
      extension: i.extension ?? null,
      size_bytes: i.size_bytes ?? null,
      sha256: i.sha256 ?? null,
      index: i.index ?? null
    }));
    break;
  }
  case 'audio': {
    const audios = Array.isArray(msg.audios) ? msg.audios : [];
    ensure(audios.length > 0, 'Unificar: audios vazio para type=audio.');
    message_content = audios[0].url;
    duration_seconds = audios[0].duration_seconds ?? null;
    attachments = audios.map(a => ({
      kind: 'audio',
      url: a.url,
      mime_type: a.mime_type,
      filename: a.filename,
      extension: a.extension ?? null,
      size_bytes: a.size_bytes ?? null,
      sha256: a.sha256 ?? null,
      index: a.index ?? null
    }));
    break;
  }
  case 'document': {
    const docs = Array.isArray(msg.documents) ? msg.documents : [];
    ensure(docs.length > 0, 'Unificar: documents vazio para type=document.');
    message_content = docs[0].url;
    caption = docs[0].caption ?? null;
    attachments = docs.map(d => ({
      kind: 'document',
      url: d.url,
      mime_type: d.mime_type,
      filename: d.filename,
      extension: d.extension ?? null,
      size_bytes: d.size_bytes ?? null,
      sha256: d.sha256 ?? null,
      index: d.index ?? null
    }));
    break;
  }
  case 'video': {
    const vids = Array.isArray(msg.videos) ? msg.videos : [];
    ensure(vids.length > 0, 'Unificar: videos vazio para type=video.');
    message_content = vids[0].url;
    caption = vids[0].caption ?? null;
    duration_seconds = vids[0].duration_seconds ?? null;
    attachments = vids.map(v => ({
      kind: 'video',
      url: v.url,
      mime_type: v.mime_type,
      filename: v.filename,
      extension: v.extension ?? null,
      size_bytes: v.size_bytes ?? null,
      sha256: v.sha256 ?? null,
      index: v.index ?? null
    }));
    break;
  }
  case 'sticker': {
    const stickers = Array.isArray(msg.stickers) ? msg.stickers : [];
    ensure(stickers.length > 0, 'Unificar: stickers vazio para type=sticker.');
    message_content = stickers[0].url;
    attachments = stickers.map(s => ({
      kind: 'sticker',
      url: s.url,
      mime_type: s.mime_type,
      filename: s.filename,
      extension: s.extension ?? null,
      size_bytes: s.size_bytes ?? null,
      sha256: s.sha256 ?? null,
      index: s.index ?? null
    }));
    break;
  }
  case 'location': {
    ensure(msg.location && typeof msg.location === 'object', 'Unificar: location ausente para type=location.');
    location = {
      latitude: msg.location.latitude,
      longitude: msg.location.longitude,
      address: msg.location.address ?? null,
      name: msg.location.name ?? null
    };
    message_content = `${location.latitude},${location.longitude}`;
    break;
  }
  case 'contact': {
    const list = Array.isArray(msg.contacts) ? msg.contacts : [];
    ensure(list.length > 0, 'Unificar: contacts vazio para type=contact.');
    contacts = list.map(c => ({
      phone: c.phone,
      name: c.name ?? null,
      org: c.org ?? null,
      vcard: c.vcard ?? null,
      index: c.index ?? null
    }));
    message_content = `${contacts[0].name ?? 'Contato'} (${contacts[0].phone})`;
    break;
  }
  case 'template': {
    ensure(msg.template && typeof msg.template === 'object', 'Unificar: template ausente para type=template.');
    template = {
      name: msg.template.name,
      namespace: msg.template.namespace ?? null,
      language: msg.template.language ?? null,
      components: msg.template.components ?? null
    };
    message_content = template.name;
    break;
  }
  default: {
    const e = new Error(`Unificar: tipo não suportado (${type}).`);
    e.statusCode = 415; throw e;
  }
}

// ---------- Política de tamanho de resposta (para Model Selector) ----------
// Regra de negócio (padrão): mídia/ações rápidas → curto; restante → longo
const isMedia = ['image','audio','document','video','sticker','location','contact','template'].includes(type);
const wantsShort =
  isMedia ||
  ctx.reply_style === 'short' ||
  (ctx.meta && ctx.meta.force_short === true);

// Permite override vindo de upstream ($json.llm_prefs?.max_chars)
const incomingMax = $json.llm_prefs?.max_chars;
const maxChars = Number.isFinite(incomingMax) ? incomingMax : (wantsShort ? 70 : 400);
const modelHint = maxChars <= 70 ? 'short' : 'long';

const llm_prefs = {
  max_chars: maxChars,
  model_hint: modelHint
};
// --------------------------------------------------------------------------

// Monta o payload padronizado para a IA
const unified = {
  user_id,
  user_name,
  message_type: type,
  message_content,
  chat_id,
  project_id,
  timestamp,
  caption,

  direction,
  attachments,
  duration_seconds,
  location,
  contacts,
  template,

  event_id: ctx.event_id ?? null,
  channel: ctx.channel ?? null,
  ia_user_id: ctx.ia_user_id ?? null,

  // útil se alguém consumir do unified
  llm_prefs
};

// bloco prontinho para LLM 
const llm_payload = {
  chat: {
    id: chat_id,
    project_id,
    channel: ctx.channel,
    timestamp,
  },
  user: {
    id: user_id,
    name: user_name
  },
  message: {
    type,
    content: message_content,
    caption,
    attachments,
    duration_seconds,
    location,
    contacts,
    template
  },
  hints: {
    is_media: isMedia,
    is_text: type === 'text',
    has_location: !!location,
    has_contacts: Array.isArray(contacts) && contacts.length > 0
  },
  llm_prefs // também dentro do bloco da LLM
};

return [{
  json: {
    // expõe no item raiz para o Model Selector ler: $json.llm_prefs.max_chars
    llm_prefs,
    unified,
    llm_payload
  }
}];

// Entrada
const p = $json.payload ?? $json;

if (!p?.project_id || !p?.chat_id) {
  const e = new Error('Policy Get: payload sem project_id/chat_id.');
  e.statusCode = 400;
  throw e;
}

const key = `${p.project_id}:${p.chat_id}`;

// 💡 Nó Code: use $getWorkflowStaticData
const store = $getWorkflowStaticData('global');

// cria estrutura, se não existir
store.chat_policies = store.chat_policies ?? {};

const row = store.chat_policies[key] ?? null;

return [{
  json: {
    payload: p,
    policy: row // ex.: { ia_disabled:true, assumed_by:'...', ... } ou null
  }
}];

const payload = $json.payload;
const policy  = $json.policy ?? null;

const ALLOWED_STEPS = new Set([
  'pré-venda',
  'qualificação',
  'medição',
  'montagem'
]);

const step = payload.project_step ?? null;
const stepAllowed = step ? ALLOWED_STEPS.has(step) : false;
const iaDisabled  = Boolean(policy?.ia_disabled === true);
const iaActive    = stepAllowed && !iaDisabled;

return [{
  json: {
    payload,
    context: {
      project_id: payload.project_id,
      chat_id: payload.chat_id,
      channel: payload.channel ?? null,
      project_step: step,
      step_allowed: stepAllowed,
      ia_disabled: iaDisabled,
      ia_active: iaActive,
      store_id: policy?.store_id ?? null,
      assumed_by: policy?.assumed_by ?? null,
      assumed_at: policy?.assumed_at ?? null
    }
  }
}];

const p = $json.payload ?? $json;

if (!p?.project_id || !p?.chat_id) {
  const e = new Error('Assumed: payload sem project_id/chat_id.');
  e.statusCode = 400;
  throw e;
}

const key = `${p.project_id}:${p.chat_id}`;

let store;
try {
  store = $getWorkflowStaticData('global');     // ✅ Code node
} catch (err) {
  store = global.__fakeStaticStore ??= {};
}

store.chat_policies = store.chat_policies ?? {};

const assumedAt = p.timestamp ?? new Date().toISOString();

store.chat_policies[key] = {
  ...(store.chat_policies[key] ?? {}),
  ia_disabled: true,
  assumed_by: p.agent_id ?? null,
  assumed_at: assumedAt,
  store_id: p.store_id ?? null,
  project_step: p.project_step ?? null,
  chat_status: p.chat_status ?? null,
  last_event: 'chat.agent_assumed',
};

return [{
  json: {
    ok: true,
    key,
    policy: store.chat_policies[key],
  }
}];

const out = $json;
console.log('CHAT ASSUMIDO:', JSON.stringify(out, null, 2));
return [{ json: { logged: true, ...out } }];

const REMOVE_ON_RELEASE = false; // ← mude para true se quiser remover a chave ao liberar

const p = $json.payload ?? $json;

// valida mínimos
if (!p?.project_id || !p?.chat_id) {
  const e = new Error('Release: payload sem project_id/chat_id.');
  e.statusCode = 400;
  throw e;
}

const key = `${p.project_id}:${p.chat_id}`;

// Obtém Static Data de forma compatível com nó Code.
// Em execução real (workflow ativado), $getWorkflowStaticData funciona.
// Em teste manual, usamos um fallback in-memory (não persiste).
let store;
try {
  store = $getWorkflowStaticData('global');  // ✅ Code node
} catch (err) {
  store = global.__fakeStaticStore ??= {};   // Fallback só p/ teste manual
}

store.chat_policies = store.chat_policies ?? {};

if (REMOVE_ON_RELEASE) {
  // Remoção total do registro
  const existed = Object.prototype.hasOwnProperty.call(store.chat_policies, key);
  delete store.chat_policies[key];

  return [{
    json: {
      ok: true,
      key,
      deleted: existed,
      last_event: 'chat.agent_released',
    }
  }];
} else {
  // Reativação mantendo histórico
  const existing = store.chat_policies[key] ?? {};
  const releasedAt = p.timestamp ?? new Date().toISOString();

  store.chat_policies[key] = {
    ...existing,
    ia_disabled: false,
    released_at: releasedAt,
    released_by: p.agent_id ?? null,
    // campos contextuais opcionais — atualiza se chegarem
    store_id: p.store_id ?? existing.store_id ?? null,
    project_step: p.project_step ?? existing.project_step ?? null,
    chat_status: p.chat_status ?? existing.chat_status ?? null,
    last_event: 'chat.agent_released',
  };

  return [{
    json: {
      ok: true,
      key,
      policy: store.chat_policies[key],
    }
  }];
}

const out = $json;
console.log('CHAT LIBERADO:', JSON.stringify(out, null, 2));
return [{ json: { logged: true, ...out } }];

/**
 * Build LLM Prompt (Comandos da IA) — classificação primeiro
 * - Se NÃO houver project_id, pergunta obrigatória: "novo x em andamento".
 * - Se HOUVER project_id, assume "em andamento" e pula a pergunta de classificação,
 *   focando em entender a demanda e rotear para a etapa correta (entre Pré-venda, Medição, Montagem, Entrega).
 * - Sempre 1 pergunta por vez. Saída OBRIGATÓRIA em JSON (schema abaixo).
 */

const assistantName = "Alice";

// FIXOS (verbatim)
const FIXED_GREETING = `Olá! Eu sou a Alice, assistente virtual da nossa loja. Obrigada pelo contato 😊`;
const FIXED_CLASSIFICATION = `Obrigada pelo interesse! Para te direcionar melhor, você já tem um projeto em andamento com a loja ou este é o seu primeiro contato?`;

const funnelAllowed = ["Pré-venda","Medição","Montagem","Entrega"];

const styleRules = `
- Mensagens curtas, 1–2 frases (no máximo 3).
- 1 pergunta por vez.
- Tom educado, positivo e profissional; emoji só quando fizer sentido (máx. 1).
- Não inventar dados da loja, prazos ou políticas.
- Se houver ambiguidade, faça 1 pergunta de esclarecimento e siga.
`;

// === Entrada ===
const p = $json.payload ?? {};
const unified = $json.unified ?? {};
const llm_payload_in = $json.llm_payload ?? {};
const bkInput = Array.isArray($json.bk_questions) && $json.bk_questions.length ? $json.bk_questions : [
  "Qual ambiente você deseja planejar? (Cozinha, suíte, sala, varanda, etc.)",
  "Esse projeto é para morar, alugar, vender ou outro motivo?",
  "O imóvel é uma casa, apartamento, comercial ou outro?"
];

// Preferências de tamanho
const incomingPrefs = $json.llm_prefs ?? unified.llm_prefs ?? llm_payload_in.llm_prefs ?? {};
const maxChars = Number.isFinite(incomingPrefs.max_chars) ? incomingPrefs.max_chars : 400;
const modelHint = maxChars <= 70 ? 'short' : 'long';
const llm_prefs = { ...incomingPrefs, max_chars: maxChars, model_hint: modelHint };

const userMessage = String(unified.message_content ?? unified.text ?? p?.message?.text ?? "").trim();
const isFirstTurn = Boolean($json.flags?.is_first_turn ?? false);

// Estado detectado do CLIENT_APP
const hasProject = Boolean(p.project_id);
const currentStep = p.project_step ?? null;

// Schema/contrato exigido da LLM
const RESPONSE_SCHEMA = {
  type: "object",
  properties: {
    reply: { type: "string" },
    classification: { type: "string", enum: ["novo","em_andamento","incerto"] },
    routed_stage: { type: ["string","null"], enum: [...funnelAllowed, null] },
    actions: {
      type: "object",
      properties: {
        update_customer_name: { type: ["string","null"] },
        capture_origin: { type: ["string","null"], enum: ["Instagram","Indicação","Outro", null] },
        labels_append: { type: "array", items: { type: "string" } },
        need_schedule: { type: "boolean" }
      },
      required: ["labels_append","need_schedule"]
    }
  },
  required: ["reply","classification","actions"]
};

// Regras obrigatórias
function buildStrictRules(bkQuestions) {
  const bkList = bkQuestions.map((q, i) => `${i + 1}. ${q}`).join("\n");
  return `
REGRAS OBRIGATÓRIAS:
1) Classificar antes de tudo:
   - "novo" (cliente novo, sem projeto em aberto) OU
   - "em_andamento" (cliente com projeto em aberto).
   Se estiver ambíguo, retorne "incerto" e faça 1 pergunta direta para esclarecer.
2) Se "novo":
   - Agradeça e explique que fará poucas perguntas.
   - Siga a BK EXATAMENTE na ordem, 1 pergunta por vez.
   - BK (ordem obrigatória):
${bkList}
3) Se "em_andamento":
   - Se já houver etapa detectada pelo sistema: use como referência inicial (não altere por conta própria).
   - Pergunte de forma breve: "Como posso te ajudar com o seu projeto?"
   - Interprete a resposta e defina "routed_stage" entre: ${funnelAllowed.join(", ")}.
   - Se a intenção estiver vaga, faça 1 pergunta breve e tente decidir a etapa.
4) Nunca mude a etapa por conta própria. Apenas informe "routed_stage" (sugestão).
5) Saída OBRIGATÓRIA em JSON VÁLIDO seguindo o schema fornecido, sem texto extra.
`;
}

function buildIdentity() {
  return `
IDENTIDADE:
- Você é ${assistantName}, assistente virtual da nossa loja de móveis planejados.
- Objetivos, na ordem:
  (1) Classificar "novo" x "em_andamento".
  (2) Se "novo": qualificar seguindo BK (ordem fixa).
  (3) Se "em_andamento": entender a demanda e sugerir "routed_stage".
`;
}

function buildOpeningBlock(hasProjectFlag, isFirst) {
  // Se não sabemos de projeto, usa a abertura fixa; se já sabemos que tem projeto, não precisa da pergunta fixa.
  if (isFirst && !hasProjectFlag) {
    return `
ABERTURA (somente 1º turno sem projeto conhecido):
- Envie EXATAMENTE estas duas linhas, sem alterar:
«${FIXED_GREETING}»
«${FIXED_CLASSIFICATION}»
`;
  }
  return ""; // sem abertura fixa
}

const generalStyle = `DIRETRIZES DE ESTILO:\n${styleRules}`;

function buildPrompt({ userMessage, isFirstTurn, hasProjectFlag, bkQuestions, maxChars, currentStep }) {
  const sections = [];
  sections.push(buildIdentity());
  sections.push(buildStrictRules(bkQuestions));
  sections.push(generalStyle);

  sections.push(`
CONSTRANGIMENTO DE TAMANHO:
- Responda em ATÉ ${maxChars} caracteres. 1 pergunta por vez.
`);

  // Abertura fixa apenas quando não temos project_id
  const opening = buildOpeningBlock(hasProjectFlag, isFirstTurn);
  if (opening) sections.push(opening);

  // Contexto operacional
  const ctx = [
    currentStep ? `Etapa atual (do sistema): ${currentStep}` : `Etapa atual (do sistema): desconhecida`,
    `Canal: ${p.channel || 'whatsapp'}`,
    `Loja: ${p.store_id || 'N/D'}`
  ].join('\n');

  // Lembrete para JSON
  const jsonReminder = `
FORMATO DE RESPOSTA (OBRIGATÓRIO):
- Retorne somente JSON válido no seguinte schema:
${JSON.stringify(RESPONSE_SCHEMA)}
`;

  const conversation = `
[MENSAGEM DO CLIENTE]
"${userMessage}"
`;

  return `${sections.join("\n").trim()}\n\n${ctx}\n${jsonReminder}\n${conversation}`;
}

// monta prompt final
const prompt = buildPrompt({
  userMessage,
  isFirstTurn,
  hasProjectFlag: hasProject,
  bkQuestions: bkInput,
  maxChars,
  currentStep
});

const meta = {
  assistant_name: assistantName,
  first_turn: isFirstTurn,
  has_project: hasProject,
  current_step: currentStep,
  project_id: p.project_id ?? null,
  chat_id: p.chat_id ?? null,
  max_chars: maxChars,
  model_hint: modelHint
};

// payload para o nó LLM
const llm_payload = {
  ...llm_payload_in,
  llm_prefs,
  // Se seu nó de LLM aceitar 'system' + 'messages', você pode já enviar assim:
  // system: "…",
  // messages: [{ role:'user', content: prompt }],
  // Caso contrário, passe 'prompt' diretamente.
};

return [{
  json: {
    llm_prefs,
    prompt,         // texto único com instruções + pedido
    schema: RESPONSE_SCHEMA, // útil para validação no parser
    meta,
    unified,
    llm_payload
  }
}];

const ctx = $json.context ?? {};
const msg = $json.message ?? {};

const ensure = (cond, message, statusCode = 400) => {
  if (!cond) {
    const e = new Error(message); e.statusCode = statusCode; throw e;
  }
};

// Campos básicos vindos do contexto
const chat_id    = ctx.chat_id    ?? null;
const project_id = ctx.project_id ?? null;
const timestamp  = ctx.timestamp  ?? new Date().toISOString();
const user_id    = ctx.customer_phone ?? null; // usamos o phone como id de usuário final
const user_name  = ctx.customer_name ?? null;

ensure(chat_id && project_id, 'Unificar: context.chat_id e context.project_id são obrigatórios.');
ensure(msg && typeof msg === 'object', 'Unificar: message ausente.');

// Mapeia por tipo
const type = msg.type;
ensure(typeof type === 'string', 'Unificar: message.type ausente.');

let message_content = null;   // texto ou conteúdo primário
let caption = null;
let attachments = [];         // lista genérica (url/mime/filename/size/sha256/..)
let duration_seconds = null;  // para áudio/vídeo
let location = null;          // para location
let contacts = null;          // para contact
let template = null;          // para template
let direction = msg.direction ?? 'inbound';

// Normaliza por tipo
switch (type) {
  case 'text': {
    ensure(typeof msg.text === 'string', 'Unificar: message.text obrigatório para type=text.');
    message_content = msg.text;
    break;
  }
  case 'image': {
    const images = Array.isArray(msg.images) ? msg.images : [];
    ensure(images.length > 0, 'Unificar: images vazio para type=image.');
    message_content = images[0].url;
    caption = images[0].caption ?? null;
    attachments = images.map(i => ({
      kind: 'image',
      url: i.url,
      mime_type: i.mime_type,
      filename: i.filename,
      extension: i.extension ?? null,
      size_bytes: i.size_bytes ?? null,
      sha256: i.sha256 ?? null,
      index: i.index ?? null
    }));
    break;
  }
  case 'audio': {
    const audios = Array.isArray(msg.audios) ? msg.audios : [];
    ensure(audios.length > 0, 'Unificar: audios vazio para type=audio.');
    message_content = audios[0].url;
    duration_seconds = audios[0].duration_seconds ?? null;
    attachments = audios.map(a => ({
      kind: 'audio',
      url: a.url,
      mime_type: a.mime_type,
      filename: a.filename,
      extension: a.extension ?? null,
      size_bytes: a.size_bytes ?? null,
      sha256: a.sha256 ?? null,
      index: a.index ?? null
    }));
    break;
  }
  case 'document': {
    const docs = Array.isArray(msg.documents) ? msg.documents : [];
    ensure(docs.length > 0, 'Unificar: documents vazio para type=document.');
    message_content = docs[0].url;
    caption = docs[0].caption ?? null;
    attachments = docs.map(d => ({
      kind: 'document',
      url: d.url,
      mime_type: d.mime_type,
      filename: d.filename,
      extension: d.extension ?? null,
      size_bytes: d.size_bytes ?? null,
      sha256: d.sha256 ?? null,
      index: d.index ?? null
    }));
    break;
  }
  case 'video': {
    const vids = Array.isArray(msg.videos) ? msg.videos : [];
    ensure(vids.length > 0, 'Unificar: videos vazio para type=video.');
    message_content = vids[0].url;
    caption = vids[0].caption ?? null;
    duration_seconds = vids[0].duration_seconds ?? null;
    attachments = vids.map(v => ({
      kind: 'video',
      url: v.url,
      mime_type: v.mime_type,
      filename: v.filename,
      extension: v.extension ?? null,
      size_bytes: v.size_bytes ?? null,
      sha256: v.sha256 ?? null,
      index: v.index ?? null
    }));
    break;
  }
  case 'sticker': {
    const stickers = Array.isArray(msg.stickers) ? msg.stickers : [];
    ensure(stickers.length > 0, 'Unificar: stickers vazio para type=sticker.');
    message_content = stickers[0].url;
    attachments = stickers.map(s => ({
      kind: 'sticker',
      url: s.url,
      mime_type: s.mime_type,
      filename: s.filename,
      extension: s.extension ?? null,
      size_bytes: s.size_bytes ?? null,
      sha256: s.sha256 ?? null,
      index: s.index ?? null
    }));
    break;
  }
  case 'location': {
    ensure(msg.location && typeof msg.location === 'object', 'Unificar: location ausente para type=location.');
    location = {
      latitude: msg.location.latitude,
      longitude: msg.location.longitude,
      address: msg.location.address ?? null,
      name: msg.location.name ?? null
    };
    message_content = `${location.latitude},${location.longitude}`;
    break;
  }
  case 'contact': {
    const list = Array.isArray(msg.contacts) ? msg.contacts : [];
    ensure(list.length > 0, 'Unificar: contacts vazio para type=contact.');
    contacts = list.map(c => ({
      phone: c.phone,
      name: c.name ?? null,
      org: c.org ?? null,
      vcard: c.vcard ?? null,
      index: c.index ?? null
    }));
    message_content = `${contacts[0].name ?? 'Contato'} (${contacts[0].phone})`;
    break;
  }
  case 'template': {
    ensure(msg.template && typeof msg.template === 'object', 'Unificar: template ausente para type=template.');
    template = {
      name: msg.template.name,
      namespace: msg.template.namespace ?? null,
      language: msg.template.language ?? null,
      components: msg.template.components ?? null
    };
    message_content = template.name;
    break;
  }
  default: {
    const e = new Error(`Unificar: tipo não suportado (${type}).`);
    e.statusCode = 415; throw e;
  }
}

// ---------- Política de tamanho de resposta (para Model Selector) ----------
// Regra de negócio (padrão): mídia/ações rápidas → curto; restante → longo
const isMedia = ['image','audio','document','video','sticker','location','contact','template'].includes(type);
const wantsShort =
  isMedia ||
  ctx.reply_style === 'short' ||
  (ctx.meta && ctx.meta.force_short === true);

// Permite override vindo de upstream ($json.llm_prefs?.max_chars)
const incomingMax = $json.llm_prefs?.max_chars;
const maxChars = Number.isFinite(incomingMax) ? incomingMax : (wantsShort ? 70 : 400);
const modelHint = maxChars <= 70 ? 'short' : 'long';

const llm_prefs = {
  max_chars: maxChars,
  model_hint: modelHint
};
// --------------------------------------------------------------------------

// Monta o payload padronizado para a IA
const unified = {
  user_id,
  user_name,
  message_type: type,
  message_content,
  chat_id,
  project_id,
  timestamp,
  caption,

  direction,
  attachments,
  duration_seconds,
  location,
  contacts,
  template,

  event_id: ctx.event_id ?? null,
  channel: ctx.channel ?? null,
  ia_user_id: ctx.ia_user_id ?? null,

  // útil se alguém consumir do unified
  llm_prefs
};

// bloco prontinho para LLM 
const llm_payload = {
  chat: {
    id: chat_id,
    project_id,
    channel: ctx.channel,
    timestamp,
  },
  user: {
    id: user_id,
    name: user_name
  },
  message: {
    type,
    content: message_content,
    caption,
    attachments,
    duration_seconds,
    location,
    contacts,
    template
  },
  hints: {
    is_media: isMedia,
    is_text: type === 'text',
    has_location: !!location,
    has_contacts: Array.isArray(contacts) && contacts.length > 0
  },
  llm_prefs // também dentro do bloco da LLM
};

return [{
  json: {
    // expõe no item raiz para o Model Selector ler: $json.llm_prefs.max_chars
    llm_prefs,
    unified,
    llm_payload
  }
}];

// Function — Build Vision Prompt (Interpretação de Imagem)
// Objetivo: instruir a IA a APENAS interpretar a(s) imagem(ns) e retornar JSON estruturado,
// sem falar com o cliente, sem classificar "novo/em_andamento" e sem cercas de código.

// ===== Utils =====
const asStr = (v) => (v === undefined || v === null) ? '' : String(v);
const sanitize = (s) => asStr(s)
  .replace(/\r\n?/g, '\n')
  .replace(/\u00A0/g, ' ')
  .replace(/[\u200B-\u200D]/g, '')
  .replace(/\s+\n/g, '\n')
  .replace(/\n{3,}/g, '\n\n')
  .trim();

const safeArr = (v) => Array.isArray(v) ? v : [];
const nowIso = () => new Date().toISOString();

// ===== Entrada esperada (do nó Extrair Imagem) =====
const ctx = $json.context || {};
const msg = $json.message || {};
const meta = $json.meta || {};
const hints = meta.hints || {};
const llmPrefsIn = ($json.llm_prefs && typeof $json.llm_prefs === 'object') ? $json.llm_prefs : null;

// Campos úteis
const channel = asStr(ctx.channel || $json.channel || 'whatsapp');
const chatId = asStr(ctx.chat_id || $json.chat_id || null);
const projectId = asStr(ctx.project_id || $json.project_id || null);
const timestamp = asStr(ctx.timestamp || $json.timestamp || nowIso());
const userId = asStr(ctx.customer_phone || ($json.user && $json.user.id) || null);
const userName = asStr(ctx.customer_name || ($json.user && $json.user.name) || null);

// Mensagem/Imagens
const caption = sanitize(msg.caption || $json.caption || '');
const attachments = safeArr(msg.attachments || msg.images).map((att, i) => ({
  url: asStr(att.url),
  mime_type: asStr(att.mime_type || att.mimetype),
  filename: asStr(att.filename || `image_${i}`),
  size_bytes: typeof att.size_bytes === 'number' ? att.size_bytes : null,
  sha256: asStr(att.sha256 || ''),
  index: typeof att.index === 'number' ? att.index : i,
}));

// Preferências do LLM
const llm_prefs = {
  // Tamanho do RESUMO técnico (não é reply ao cliente)
  max_chars: (llmPrefsIn && Number.isFinite(llmPrefsIn.max_chars)) ? llmPrefsIn.max_chars : 1200,
  model_hint: (llmPrefsIn && llmPrefsIn.model_hint) ? String(llmPrefsIn.model_hint) : 'vision',
};

// Um resumo simples dos arquivos para o prompt
const filesList = attachments.map(a => `- ${a.filename} (${a.mime_type || 'mime desconhecido'})`).join('\n');
const captionLine = caption ? `Legenda do usuário: "${caption}"` : 'Sem legenda fornecida.';

// ===== PROMPT (apenas interpretação) =====
const prompt = sanitize(`
Você é um analista de VISÃO especializado em **móveis planejados**. Sua tarefa é interpretar APENAS a(s) imagem(ns) recebidas e retornar um **JSON válido** extremamente detalhado e útil para continuidade do atendimento técnico.

Regras de ouro:
- NÃO escreva mensagens ao cliente.
- NÃO classifique estágio ("novo/em_andamento"), NÃO inclua "routed_stage".
- NÃO use cercas de código (sem \`\`\`).
- Retorne **APENAS JSON** no SCHEMA abaixo, em português do Brasil.
- Se houver múltiplas imagens, considere todas para inferências; mas produza um resultado consolidado (um único objeto "vision_result") com **o melhor entendimento do conjunto**.
- Seja preciso e técnico; evite floreios.
- Use unidades explícitas quando possível; normalize medidas para **cm** quando houver conversão segura.

O que analisar (mínimo):
1) **Tipo principal** da imagem (enum): "documento", "planta_baixa", "ambiente_foto", "referencia_design", "etiqueta_produto", "outro", "desconhecido".
2) **Resumo objetivo** do conteúdo (até ${llm_prefs.max_chars} caracteres).
3) **OCR**: texto útil como medidas, rótulos, códigos, escalas, títulos de documento, fabricante, coleção, padrões de corte, etc. Se ilegível, use null.
4) **Entidades-chave** (strings curtas): cômodos (cozinha/sala/quarto/área de serviço/banheiro), materiais e superfícies aparentes (MDF/MDP/mármore/granito/quartzo/vidro/inox/laca), ferragens (corrediças dobradiças pistão trilho), eletros (forno cooktop coifa micro-ondas geladeira lava-louças), estilos (minimalista industrial clássico contemporâneo), pontos críticos (pilar viga shaft hidráulica elétrica janela porta tomada quadro de luz coluna esgoto).
5) **Medidas** detectáveis e/ou inferíveis (com unidade e fonte): identificar o que é explícito (a partir da imagem/ocr) e o que é apenas estimativa com baixa confiança.
6) **Restrições**: pé-direito, vãos, interferências, inclinações, quinas vivas, recortes, rebaixo de gesso, rodapés altos, desníveis, etc.
7) **Acompanhamentos (followups)**: até 5 perguntas/solicitações objetivas e acionáveis para avançar (medidas faltantes, ângulos adicionais, preferências de acabamento, lista de eletros, etc.).

Aprimore com os campos opcionais abaixo (quando fizer sentido):
- **subtype**: ex.: "cozinha_linear", "cozinha_em_L", "cozinha_com_ilha", "closet", "banheiro", "sala_tv", "home_office", "lavanderia".
- **layout**: leitura espacial: paredes A/B/C/D, posição relativa de portas/janelas/pilares/shaft/tomadas/tubulações; se possível, **posições em porcentagem** no eixo (x,y) relativo à imagem (0–100).
- **materials**: lista de materiais e **acabamentos** prováveis (ex.: MDF amadeirado carvalho; laca fosca branca; puxador perfil alumínio; vidro incolor; pedra quartzo branco).
- **color_palette**: até 6 cores relevantes ["#RRGGBB" ou nomes comuns] com papel (ex.: "marcenaria", "bancada", "parede", "piso").
- **lighting**: natural (janela/porta) e artificial (embutido, trilho, pendente), temperatura aparente (fria/neutra/quente).
- **appliances_hardware**: lista estruturada de eletros e ferragens identificadas pelo nome comum (e modelo se constar no OCR).
- **document_meta** (se "documento" ou "etiqueta_produto"): tipo_documento (orçamento, memorial, ART/RRT, manual, etiqueta), emissor, data, cliente, referências de projeto, numeração de páginas, escala (ex.: 1:50), carimbos/assinaturas quando presentes.
- **measurement_candidates**: lista de objetos com {label, value, unit, source: "ocr"|"visual_estimate"|"inferred", confidence}.
- **risks_flags**: ["medidas_ilegiveis","baixa_iluminacao","oclusao","perspectiva_distorta","possivel_erro_de_escala"].
- **missing_info**: lista do que impede orçamento/projeto (ex.: medida parede B, altura alvenaria, posição exata do ponto de gás).
- **recommended_shots**: instruções de novas fotos (ex.: "canto esquerdo em 90º", "parede B frontal com trena visível", "ponto de água sob a pia").

SCHEMA DE RESPOSTA (OBRIGATÓRIO, APENAS JSON):
{
  "vision_result": {
    "detected_type": "documento|planta_baixa|ambiente_foto|referencia_design|etiqueta_produto|outro|desconhecido",
    "summary": "string",
    "ocr_text": "string|null",
    "key_entities": ["string", "..."],
    "dimensions": {
      "units": "mm|cm|m|null",
      "values": ["string"]  // ex.: ["Parede A: 320cm", "Bancada: 180cm", "Pé-direito: 265cm"]
    },
    "constraints": ["string"],
    "confidence": 0.0,
    "followups": ["string"],

    // ===== OPCIONAIS (NÃO QUEBRAM PIPELINE) =====
    "subtype": "string|null",
    "layout": {
      "walls": ["Parede A","Parede B","Parede C","Parede D"],
      "openings": [
        {"type": "porta|janela", "wall": "Parede A", "approx_position_pct": {"x": 70, "y": 50}, "notes": "janela baixa"}
      ],
      "structures": [
        {"type": "pilar|viga|shaft|coluna", "wall": "Parede B", "approx_position_pct": {"x": 15, "y": 80}, "notes": "pilar 20x20 (estimado)"}
      ],
      "outlets": [
        {"type": "tomada|hidraulica|gas|esgoto", "wall": "Parede C", "approx_position_pct": {"x": 40, "y": 60}, "notes": "tubo de esgoto aparente"}
      ]
    },
