// Parse Vision Output
function safeParse(s){ try { return JSON.parse(s); } catch { return null; } }

const raw = $json.content;
let vr = null;

if (typeof raw === 'string') {
  // remove cercas de código se vierem
  const cleaned = raw.replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/,'').trim();
  const obj = safeParse(cleaned);
  vr = obj?.vision_result ?? obj ?? null;
} else if (raw && typeof raw === 'object') {
  vr = raw.vision_result ?? raw;
}

return [{
  json: {
    ...$json,
    vision_result: vr || {
      detected_type: 'desconhecido',
      summary: null,
      ocr_text: null,
      key_entities: [],
      dimensions: { units: null, values: [] },
      constraints: [],
      confidence: 0
    }
  }
}];

// Compose Image Reply (Alice) — versão com pass-through e session_id

// ===== helpers
const asStr = (v) => v == null ? '' : String(v);
const clamp01 = (x) => Math.max(0, Math.min(1, Number(x)));
const hasVals = (arr) => Array.isArray(arr) && arr.length > 0;
const pick = (...xs) => xs.find(v => v !== undefined && v !== null && v !== '') ?? null;

// ===== inputs
const ctx = $json.context || {};
const msg = $json.message || {};
const meta = $json.meta || {};
const uni = $json.unified || {};
const vr  = $json.vision_result || {};

const caption = asStr(msg.caption);
const detected = asStr(vr.detected_type).toLowerCase();
const conf = clamp01(vr.confidence);
const dims = vr.dimensions || { units: null, values: [] };
const hasDims = hasVals(dims.values);
const sum = asStr(vr.summary);

// —— relevância
const RELEVANTES = new Set(['ambiente_foto','planta_baixa','referencia_design','documento','etiqueta_produto']);
const relevante = RELEVANTES.has(detected);

// —— classificação/etapa sugerida
const hasProject = !!pick(ctx.project_id, uni.project_id);
let classification = hasProject ? 'em_andamento' : 'incerto';
let routed_stage = null;

if (relevante && conf >= 0.7) {
  if (detected === 'planta_baixa' && hasDims) routed_stage = 'Medição';
  else if (detected === 'ambiente_foto') routed_stage = 'Medição';
  else routed_stage = 'Pré-venda';
}

// —— resposta
let reply;
const labels = [];
let need_schedule = false;

if (!vr || conf < 0.4 || detected === 'desconhecido') {
  labels.push('imagem_irrelevante');
  const ped = 'Pode enviar uma foto do ambiente (parede inteira) ou uma planta baixa com medidas?';
  reply = sum ? `${sum}. ${ped}` : ped;
} else if (detected === 'ambiente_foto') {
  labels.push('imagem_ambiente');
  if (!hasDims) {
    reply = `${sum || 'Foto recebida.'} Consegue informar a largura da parede e a altura do piso ao teto?`;
  } else {
    reply = `${sum || 'Perfeito!'} Posso seguir com o orçamento. Prefere por aqui ou agendar a medição?`;
    need_schedule = true;
  }
} else if (detected === 'planta_baixa') {
  labels.push('imagem_planta');
  if (!hasDims) {
    reply = `${sum || 'Planta recebida.'} Pode confirmar largura x altura da parede e indicar portas/janelas?`;
  } else {
    reply = `${sum || 'Planta com medidas recebida.'} Avanço no orçamento ou deseja marcar a medição?`;
    need_schedule = true;
  }
} else if (detected === 'referencia_design') {
  labels.push('imagem_referencia');
  reply = `${sum || 'Referência recebida.'} Tem preferência de acabamento (MDF, laca, vidro) e faixa de investimento?`;
} else if (detected === 'documento') {
  labels.push('imagem_documento');
  reply = `${sum || 'Documento recebido.'} Deseja que eu considere essas informações no orçamento?`;
} else if (detected === 'etiqueta_produto') {
  labels.push('imagem_etiqueta');
  reply = `${sum || 'Informação do produto recebida.'} Incluo esse modelo no projeto?`;
} else {
  labels.push('imagem_outro');
  const ped = 'Pode enviar a foto do ambiente/paredes ou uma planta baixa com medidas para avançarmos?';
  reply = sum ? `${sum}. ${ped}` : ped;
}

// ====== garantir session_id (sem sobrescrever se já existir)
const session_id = pick(
  $json.session_id,
  ctx.session_id,
  meta.session_id,
  uni.session_id,
  $json.llm_payload?.chat?.session_id,
  $json.chat?.session_id,
  // fallback determinístico (último recurso)
  (ctx.chat_id || uni.chat_id) && (ctx.project_id || uni.project_id)
    ? `${(ctx.chat_id||uni.chat_id)}:${(ctx.project_id||uni.project_id)}`
    : null
);

// ====== objeto padrão da Alice (schema)
const agentFlat = {
  reply,
  classification,
  routed_stage,
  actions: {
    update_customer_name: null,
    capture_origin: null,
    labels_append: labels,
    need_schedule
  }
};

// ====== retorno com PASS-THROUGH + campos novos
return [{
  json: {
    // mantém absolutamente tudo que veio antes
    ...$json,

    // injeta/atualiza session_id em todos os lugares úteis
    session_id: session_id || $json.session_id || null,
    context: {
      ...ctx,
      session_id: session_id || ctx.session_id || null,
    },
    unified: {
      ...uni,
      session_id: session_id || uni.session_id || null,
    },

    // mantém o laudo de visão
    vision_result: vr,

    // entrega no formato plano (compatível com nós seguintes)
    ...agentFlat,

    // e também em um bloco agrupado (útil para logs/DB)
    agent_reply: {
      ...agentFlat,
      confidence: conf,
      detected_type: detected,
      used_dims: hasDims
    }
  }
}];

// Function — Build Reply Prompt (From Vision)
// Objetivo: instruir a Alice a compor a resposta ao cliente com base no vision_result,
