// ===== Utils =====
const asStr = (v) => (v === undefined || v === null) ? '' : String(v);
const sanitize = (s) => asStr(s)
  .replace(/\r\n?/g, '\n')
  .replace(/\u00A0/g, ' ')
  .replace(/[\u200B-\u200D]/g, '')
  .replace(/\s+\n/g, '\n')
  .replace(/\n{3,}/g, '\n\n')
  .trim();
const safeArr = (v) => Array.isArray(v) ? v : [];

// ===== Inputs vindos do Merge =====
const ctx  = $json.context || {};
const msg  = $json.message || {};
const meta = $json.meta || {};
const uni  = $json.unified || {};
const vr   = $json.vision_result || {}; // {detected_type, summary, ocr_text, key_entities[], dimensions{units,values[]}, constraints[], confidence, followups[]}

const channel   = asStr(ctx.channel || uni.channel || 'whatsapp');
