// ============================================================================
// SCHEMA DE RESPOSTA ESPERADA
// ============================================================================
const RESPONSE_SCHEMA = {
  type: "object",
  required: [
    "reply",
    "mensagem_cliente",
    "fluxo",
    "classification",
    "dados_localizacao",
    "status_localizacao",
    "proxima_pergunta",
    "projectData",
    "acoes_banco_dados",
    "followup"
  ],
  properties: {
    reply: { type: "string" },
    mensagem_cliente: { type: "string" },
    fluxo: { type: "string", enum: ["localizacao_projeto"] },
    classification: { type: "string", enum: ["localizacao_projeto"] },
    dados_localizacao: { type: "object" },
    status_localizacao: {
      type: "string",
      enum: [
        "aguardando_dados",
        "buscando",
        "encontrado",
        "nao_encontrado",
        "transferir_humano"
      ]
    },
    proxima_pergunta: { type: ["string", "null"] },
    projectData: { type: ["object", "null"] },
    acoes_banco_dados: { type: "array" },
    followup: { type: "object" }
  }
};

// ============================================================================
// FUNÇÃO PRINCIPAL PARA BUILD DO PAYLOAD DO LLM
// ============================================================================
function buildCompletePayload({
  userMessage,
  isFirstTurn,
  hasProject,
  maxChars,
  currentStep,
  conversationHistory,
  customerData,
  projectData,
  assistantName = "Sophia",
  modelHint = "gpt-4.1-mini",
  llm_payload_in = {}
}) {
  const prompt = buildDynamicPrompt({
    userMessage,
    isFirstTurn,
    hasProjectFlag: hasProject,
    maxChars,
    currentStep,
    conversationHistory,
    customerData,
    projectData
  });

  const meta = {
    assistant_name: assistantName,
    first_turn: isFirstTurn,
    has_project: hasProject,
    current_step: currentStep,
    project_id: projectData?.project_id ?? null,
    chat_id: customerData?.chat_id ?? null,
    customer_phone: customerData?.phone ?? null,
    max_chars: maxChars,
    model_hint: modelHint,
    timestamp: new Date().toISOString()
  };

  const llm_prefs = {
    model: modelHint,
    temperature: 0.4, // mais determinístico pra evitar alucinação na busca
    max_tokens: Math.ceil(maxChars * 1.5),
    response_format: { type: "json_object" }
  };

  const llm_payload = {
    ...llm_payload_in,
    ...llm_prefs,
    messages: [
      {
        role: "user",
        content: JSON.stringify(prompt, null, 2)
      }
    ]
  };

  return [
    {
      json: {
        llm_prefs,
        prompt: JSON.stringify(prompt),
        schema: RESPONSE_SCHEMA,
        meta,
        llm_payload,
        raw_data: {
          userMessage,
          isFirstTurn,
          hasProject,
          currentStep,
          customerData
        }
      }
    }
  ];
}

