// "query" sempre contém a entrada enviada pelo agente.
// Neste caso: a lista de projetos retornada pela API /projects.
const projetos = query;

function resposta(obj) {
  return JSON.stringify(obj, null, 2);
}

// Se não veio array ou está vazio
if (!Array.isArray(projetos) || projetos.length === 0) {
  return resposta({
    found: false,
    reason: "NO_PROJECTS_FOUND",
    project_id: null,
    project: null
  });
}

// Se houver só um projeto, retorna direto
if (projetos.length === 1) {
  const p = projetos[0];
  return resposta({
    found: true,
    project_id: p.id,
    project: p
  });
}

// Se houver vários projetos, escolher o mais atualizado (updated_at mais recente)
projetos.sort((a, b) => {
  const da = new Date(a.updated_at ?? a.created_at ?? 0);
  const db = new Date(b.updated_at ?? b.created_at ?? 0);
  return db - da; // ordem desc
});

const selecionado = projetos[0];

// Retorna projeto selecionado e id
return resposta({
  found: true,
  project_id: selecionado.id,
  project: selecionado
});

// Este Tool recebe os dados de UM projeto na variável "query".
// "query" pode vir como string JSON ou como objeto; tratamos os dois casos.
// O retorno SEMPRE será uma string JSON contendo a propriedade "projectData".

function toObject(input) {
  if (input === null || input === undefined) return null;
  if (typeof input === 'object') return input;
  try {
    return JSON.parse(String(input));
  } catch {
    return null;
  }
}

function resposta(obj) {
  return JSON.stringify(obj, null, 2);
}

// Converte a entrada em objeto
const projeto = toObject(query);

if (!projeto || typeof projeto !== 'object') {
  return resposta({
    ok: false,
    reason: "INVALID_PROJECT_INPUT",
    projectData: null
  });
}

// Tentamos ser tolerantes a diferentes nomes de campos
const projectData = {
  project_id:      projeto.id ?? projeto.project_id ?? null,
  project_number:  projeto.number ?? projeto.project_number ?? null,
  owner_name:      projeto.owner_name ?? projeto.titular ?? projeto.client_name ?? null,
  project_type:    projeto.project_type ?? projeto.type ?? null,
  status:          projeto.status ?? null,
  assigned_to:     projeto.assigned_to ?? projeto.responsible ?? projeto.responsavel_humano ?? null,
  created_at:      projeto.created_at ?? null,
  updated_at:      projeto.updated_at ?? null,

  // Campos extras úteis, se existirem
  step:            projeto.step ?? projeto.current_step ?? null,
  store_name:      projeto.store_name ?? projeto.loja ?? null
};

return resposta({
  ok: true,
  projectData
});

// Code – Ajuste output AI (Localização)

// 1) Pega a saída crua do AI Agent
// Geralmente vem em $json.output como string JSON
// Mas deixei fallback pra segurança
const raw =
  $json.output ??
  $json.aiResponse ??
  $json.response ??
  $json.text ??
  $json;

// 2) Se já veio como objeto JSON, só retorna
if (raw && typeof raw === "object" && !Array.isArray(raw)) {
  return [{ json: raw }];
}

// 3) Se for array com objeto dentro -> retorna o primeiro item
if (Array.isArray(raw) && raw.length > 0 && typeof raw[0] === "object") {
  return [{ json: raw[0] }];
}

// 4) Agora tratamos como string
const rawStr = String(raw || "").trim();

// Remove markdown ```json ou ``` se houver
const cleaned = rawStr
  .replace(/```json/gi, "")
  .replace(/```/g, "")
  .trim();

// 5) Tentar fazer parse do JSON
let parsed;
try {
  parsed = JSON.parse(cleaned);
} catch (e) {
  throw new Error(
    "Falha ao fazer parse do JSON retornado pela AI (localização). Saída recebida:\n\n" +
      cleaned +
      "\n\nErro: " +
      e.message
  );
}

// 6) Retorna no formato padrão do n8n
return [{ json: parsed }];

// Code – Histórico (localizacao_projeto)

// 1. Resolver dados do item

// Mensagem original do cliente
const userMessage =
  $json.mensagem_cliente ??
  $json.userMessage ??
  "";

// Mensagem da IA
const aiText = $json.reply ?? "";

// session_id (id do chat)
const sessionId =
