// Code – Reset Session (Localização)

const item = $json;

const chatId = item.llm_payload?.chat?.id || item.session_id || item.chat_id;

const newSessionId = `${chatId}-localizacao-${Date.now()}`;

item.session_id = newSessionId;
item.current_step = "localizacao_projeto";

item.session_origin = {
