// Code - Reanexar Contexto (após PUT Atendimento Inicial)

// Resposta do PUT (o que veio do CLIENT_APP)
const putResp = $json;

// Payload completo original (antes do PUT)
const original = $node["Merge - Combinação JWT e AI"].json;

// Junta tudo: mantém o contexto e guarda a resposta do PUT separado
return [
  {
    json: {
      ...original,              // classification, fluxo, llm_payload, token, etc
      put_atendimento: putResp  // opcional: pra debug/log
    }
  }
];

const ctx = $json.context ?? {};
const msg = $json.message ?? {};

const ensure = (cond, message, statusCode = 400) => {
  if (!cond) {
    const e = new Error(message); e.statusCode = statusCode; throw e;
  }
};

// Campos básicos vindos do contexto
const chat_id    = ctx.chat_id    ?? null;
const project_id = ctx.project_id ?? null;
const timestamp  = ctx.timestamp  ?? new Date().toISOString();
const user_id    = ctx.customer_phone ?? null; // usamos o phone como id de usuário final
const user_name  = ctx.customer_name ?? null;

ensure(chat_id && project_id, 'Unificar: context.chat_id e context.project_id são obrigatórios.');
ensure(msg && typeof msg === 'object', 'Unificar: message ausente.');

// Mapeia por tipo
const type = msg.type;
ensure(typeof type === 'string', 'Unificar: message.type ausente.');

let message_content = null;   // texto ou conteúdo primário
let caption = null;
let attachments = [];         // lista genérica (url/mime/filename/size/sha256/..)
let duration_seconds = null;  // para áudio/vídeo
let location = null;          // para location
let contacts = null;          // para contact
let template = null;          // para template
let direction = msg.direction ?? 'inbound';

// Normaliza por tipo
switch (type) {
  case 'text': {
    ensure(typeof msg.text === 'string', 'Unificar: message.text obrigatório para type=text.');
    message_content = msg.text;
    break;
  }
  case 'image': {
    const images = Array.isArray(msg.images) ? msg.images : [];
    ensure(images.length > 0, 'Unificar: images vazio para type=image.');
    message_content = images[0].url;
    caption = images[0].caption ?? null;
    attachments = images.map(i => ({
      kind: 'image',
      url: i.url,
      mime_type: i.mime_type,
      filename: i.filename,
      extension: i.extension ?? null,
      size_bytes: i.size_bytes ?? null,
      sha256: i.sha256 ?? null,
      index: i.index ?? null
    }));
    break;
  }
  case 'audio': {
    const audios = Array.isArray(msg.audios) ? msg.audios : [];
    ensure(audios.length > 0, 'Unificar: audios vazio para type=audio.');
    message_content = audios[0].url;
    duration_seconds = audios[0].duration_seconds ?? null;
    attachments = audios.map(a => ({
      kind: 'audio',
      url: a.url,
      mime_type: a.mime_type,
      filename: a.filename,
      extension: a.extension ?? null,
      size_bytes: a.size_bytes ?? null,
      sha256: a.sha256 ?? null,
      index: a.index ?? null
    }));
    break;
  }
  case 'document': {
    const docs = Array.isArray(msg.documents) ? msg.documents : [];
    ensure(docs.length > 0, 'Unificar: documents vazio para type=document.');
    message_content = docs[0].url;
    caption = docs[0].caption ?? null;
    attachments = docs.map(d => ({
      kind: 'document',
      url: d.url,
      mime_type: d.mime_type,
      filename: d.filename,
      extension: d.extension ?? null,
      size_bytes: d.size_bytes ?? null,
      sha256: d.sha256 ?? null,
      index: d.index ?? null
    }));
    break;
  }
  case 'video': {
    const vids = Array.isArray(msg.videos) ? msg.videos : [];
    ensure(vids.length > 0, 'Unificar: videos vazio para type=video.');
    message_content = vids[0].url;
    caption = vids[0].caption ?? null;
    duration_seconds = vids[0].duration_seconds ?? null;
    attachments = vids.map(v => ({
      kind: 'video',
      url: v.url,
      mime_type: v.mime_type,
      filename: v.filename,
      extension: v.extension ?? null,
      size_bytes: v.size_bytes ?? null,
      sha256: v.sha256 ?? null,
      index: v.index ?? null
    }));
    break;
  }
  case 'sticker': {
    const stickers = Array.isArray(msg.stickers) ? msg.stickers : [];
    ensure(stickers.length > 0, 'Unificar: stickers vazio para type=sticker.');
    message_content = stickers[0].url;
    attachments = stickers.map(s => ({
      kind: 'sticker',
      url: s.url,
      mime_type: s.mime_type,
      filename: s.filename,
      extension: s.extension ?? null,
      size_bytes: s.size_bytes ?? null,
      sha256: s.sha256 ?? null,
      index: s.index ?? null
    }));
    break;
  }
  case 'location': {
    ensure(msg.location && typeof msg.location === 'object', 'Unificar: location ausente para type=location.');
    location = {
      latitude: msg.location.latitude,
      longitude: msg.location.longitude,
      address: msg.location.address ?? null,
      name: msg.location.name ?? null
    };
    message_content = `${location.latitude},${location.longitude}`;
    break;
  }
  case 'contact': {
    const list = Array.isArray(msg.contacts) ? msg.contacts : [];
    ensure(list.length > 0, 'Unificar: contacts vazio para type=contact.');
    contacts = list.map(c => ({
      phone: c.phone,
      name: c.name ?? null,
      org: c.org ?? null,
      vcard: c.vcard ?? null,
      index: c.index ?? null
    }));
    message_content = `${contacts[0].name ?? 'Contato'} (${contacts[0].phone})`;
    break;
  }
  case 'template': {
    ensure(msg.template && typeof msg.template === 'object', 'Unificar: template ausente para type=template.');
    template = {
      name: msg.template.name,
      namespace: msg.template.namespace ?? null,
      language: msg.template.language ?? null,
      components: msg.template.components ?? null
    };
    message_content = template.name;
    break;
  }
  default: {
    const e = new Error(`Unificar: tipo não suportado (${type}).`);
    e.statusCode = 415; throw e;
  }
}

// ---------- Política de tamanho de resposta (para Model Selector) ----------
// Regra de negócio (padrão): mídia/ações rápidas → curto; restante → longo
const isMedia = ['image','audio','document','video','sticker','location','contact','template'].includes(type);
const wantsShort =
  isMedia ||
  ctx.reply_style === 'short' ||
  (ctx.meta && ctx.meta.force_short === true);

// Permite override vindo de upstream ($json.llm_prefs?.max_chars)
const incomingMax = $json.llm_prefs?.max_chars;
const maxChars = Number.isFinite(incomingMax) ? incomingMax : (wantsShort ? 70 : 400);
const modelHint = maxChars <= 70 ? 'short' : 'long';

const llm_prefs = {
  max_chars: maxChars,
  model_hint: modelHint
};
// --------------------------------------------------------------------------

// Monta o payload padronizado para a IA
const unified = {
  user_id,
  user_name,
  message_type: type,
  message_content,
  chat_id,
  project_id,
  timestamp,
  caption,

  direction,
  attachments,
  duration_seconds,
  location,
  contacts,
  template,

  event_id: ctx.event_id ?? null,
  channel: ctx.channel ?? null,
  ia_user_id: ctx.ia_user_id ?? null,

  // útil se alguém consumir do unified
  llm_prefs
};

// bloco prontinho para LLM 
const llm_payload = {
  chat: {
    id: chat_id,
    project_id,
    channel: ctx.channel,
    timestamp,
  },
  user: {
    id: user_id,
    name: user_name
  },
  message: {
    type,
    content: message_content,
    caption,
    attachments,
    duration_seconds,
    location,
    contacts,
    template
  },
  hints: {
    is_media: isMedia,
    is_text: type === 'text',
    has_location: !!location,
    has_contacts: Array.isArray(contacts) && contacts.length > 0
  },
  llm_prefs // também dentro do bloco da LLM
};

return [{
  json: {
    // expõe no item raiz para o Model Selector ler: $json.llm_prefs.max_chars
    llm_prefs,
    unified,
    llm_payload
  }
}];

// ============================================================================
// SOURCE FOR PROMPT (USER MESSAGE) - AGENTE "ATENDIMENTO INICIAL" (n8n Function)
// ============================================================================

/**
 * Função principal para construir o prompt dinâmico baseado no contexto
 * (Agente 1 - Atendimento Inicial)
 */
function buildDynamicPrompt({
  userMessage,
  isFirstTurn,
  hasProjectFlag,
  bkQuestions,
  maxChars,
  currentStep,
  conversationHistory = [],
  customerData = {},
  projectData = null
}) {
  const promptSections = [];

  // ================================================================
  // 1 — CONTEXTO BÁSICO
  // ================================================================
  promptSections.push({
    section: "CONTEXT",
    data: {
      turno: isFirstTurn ? "PRIMEIRO_CONTATO" : "CONVERSA_EM_ANDAMENTO",
      mensagem_usuario: userMessage,
      historico: conversationHistory.slice(-8),
      dados_cliente: customerData || {},
      cliente_tem_projeto_sinalizado: hasProjectFlag || false,
      etapa_atual_fluxo: currentStep || "atendimento_inicial"
    },
    instruction: `
      Você é a AGENTE DE ATENDIMENTO INICIAL.

      Sua função é APENAS:
      1. Responder o cliente de forma educada, com saudação adequada ao contexto.
      2. Entender, a partir da mensagem dele, qual tipo de intenção ele tem.
      3. Classificar o fluxo correto para o próximo atendimento:
         - "qualificacao"          → novo projeto / orçamento
         - "localizacao_projeto"   → projeto em andamento
         - "informacao"            → informações gerais da loja, condições, atendimento
         - "duvida"                → quando ainda está genérico/ambíguo

      Você NÃO deve:
      - Fazer perguntas de qualificação detalhadas.
      - Pedir dados como nome completo, telefone, tipo de imóvel etc.
      - Tentar localizar projetos no sistema.
      - Acionar qualquer ferramenta ou etapa técnica do sistema.

      O seu papel é: SAUDAÇÃO + TRIAGEM + DEFINIR "fluxo".
    `.trim()
  });

  // ================================================================
  // 2 — REGRAS DE SAUDAÇÃO
  // ================================================================
  promptSections.push({
    section: "SAUDACAO",
    instruction: `
      Se for o PRIMEIRO contato (isFirstTurn = true):
      - Sempre responda com uma saudação amigável + "como posso ajudar?".
      - Exemplo: 
        "Olá! Tudo bem? Seja bem-vindo(a)! Como posso te ajudar hoje?"

      Se NÃO for o primeiro contato:
      - Mantenha o tom educado e natural, levando em conta o histórico.
      - Você pode responder algo como:
        "Entendi! Me conta um pouco melhor para eu te ajudar da melhor forma."

      Importante:
      - Nunca seja seco ou robótico.
      - Não faça perguntas longas demais nesse agente.
      - Mantenha a resposta curta, direta e clara.
    `.trim()
  });

  // ================================================================
  // 3 — TRIAGEM DE INTENÇÃO (DEFINIR FLUXO)
  // ================================================================
  promptSections.push({
    section: "TRIAGEM_INTENCAO",
    instruction: `
      Sua missão é classificar a intenção do cliente em UMA das opções abaixo.
      Use SEMPRE a que fizer mais sentido pela mensagem do usuário:

      1) fluxo = "qualificacao"
         Use quando a mensagem indicar que o cliente quer:
         - fazer orçamento
         - iniciar um projeto
         - planejar um ambiente
         - "quero fazer móveis planejados", "quero orçamento", "quero planejar minha cozinha", etc.

      2) fluxo = "localizacao_projeto"
         Use quando a mensagem indicar que o cliente:
         - já tem projeto em andamento
         - menciona número de projeto
         - fala de etapas (montagem, entrega, aprovação, etc.)
         - fala em "acompanhar meu projeto", "ver andamento", "já estou com vocês", etc.

      3) fluxo = "informacao"
         Use quando a mensagem indicar que o cliente:
         - quer informações gerais da loja
         - pergunta sobre atendimento, prazos, formas de pagamento
         - pergunta sobre como funciona o processo em geral
         - pergunta sobre regras, políticas, horários etc.

      4) fluxo = "duvida"
         Use quando:
         - a mensagem for apenas cumprimento (ex.: "oi", "bom dia", "tudo bem?")
         - a mensagem ainda estiver muito genérica e você não consegue saber
           se é orçamento, projeto em andamento ou só informação.
         Nesse caso, responda com uma saudação amigável + uma pergunta aberta
         para entender melhor ("Perfeito! Me conta, você quer fazer um novo projeto
         ou falar sobre algum projeto que já tem conosco?", por exemplo).

      IMPORTANTE:
      - Não invente contexto que não existe.
      - Se estiver ambíguo, prefira "duvida" e faça uma pergunta simples para clarear.
    `.trim()
  });

  // ================================================================
  // 4 — REGRAS DO FORMATO DE RESPOSTA
  // ================================================================
  promptSections.push({
    section: "RESPONSE_RULES",
    instruction: `
      Você DEVE SEMPRE responder em formato JSON, com os seguintes campos:

      {
        "reply": "mensagem que será enviada ao cliente",
        "mensagem_cliente": "mensagem original do cliente, sem alteração",
        "fluxo": "qualificacao | localizacao_projeto | informacao | duvida",
        "classification": "igual ao campo fluxo",
        "acoes_banco_dados": [],
        "followup": {
          "needs_followup": false,
          "topic": "",
          "timeout_minutes": 0
        }
      }

      Campo "reply":
      - É a mensagem que será enviada ao cliente.
      - Deve ser clara, curta e amigável.
      - Pode conter saudação + uma pergunta simples, se necessário para entender melhor.

      Campo "mensagem_cliente":
      - Deve conter EXATAMENTE a mensagem que o cliente enviou.
      - Não altere, não resuma, não traduza, não mexa.

      Campo "fluxo":
      - Deve ser um dos valores exatos:
        "qualificacao", "localizacao_projeto", "informacao" ou "duvida".

      Campo "classification":
      - Use o MESMO valor escolhido em "fluxo".

      Campo "acoes_banco_dados":
      O campo "acoes_banco_dados" deve sempre incluir o registro da mensagem do cliente e da mensagem enviada pela IA.

      Use este formato:

      "acoes_banco_dados": [
        {
          "operacao": "SALVAR_MENSAGEM",
           "dados": {
            "mensagem_cliente": "<mensagem_original_do_cliente>",
            "mensagem_ia": "<reply>"
          }
        }
      ]

      Campo "followup":
      - Neste agente, o padrão é:
        { "needs_followup": false, "topic": "", "timeout_minutes": 0 }.
    `.trim()
  });

  // ================================================================
  // PROMPT FINAL
  // ================================================================
  const finalPrompt = {
    prompt_version: "1.0-atendimento-inicial",
    timestamp: new Date().toISOString(),
    sections: promptSections,
    user_message: userMessage,
    response_requirements: {
      format:
        "JSON puro com os campos: reply, mensagem_cliente, fluxo, classification, acoes_banco_dados, followup. " +
        "NÃO use markdown, NÃO use ```json, NÃO retorne texto fora do JSON.",
      max_length: maxChars,
      tone: "amigável, direto e profissional",
      mandatory_fields: [
        "reply",
        "mensagem_cliente",
        "fluxo",
        "classification",
        "acoes_banco_dados",
        "followup"
      ]
    }
  };

  return finalPrompt;
}

// ============================================================================
// SCHEMA DE RESPOSTA ESPERADA DA IA - AGENTE ATENDIMENTO INICIAL
// ============================================================================

const RESPONSE_SCHEMA = {
  type: "object",
  required: [
    "reply",
    "mensagem_cliente",
    "fluxo",
    "classification",
    "acoes_banco_dados",
    "followup"
  ],
  properties: {
    reply: {
      type: "string",
      description: "Mensagem que será enviada ao cliente.",
      maxLength: 2000
    },
    mensagem_cliente: {
      type: "string",
      description:
        "Mensagem original enviada pelo cliente, sem qualquer alteração.",
      maxLength: 2000
    },
    fluxo: {
      type: "string",
      enum: ["qualificacao", "localizacao_projeto", "informacao", "duvida"],
      description:
        "Define qual fluxo será seguido no n8n após o atendimento inicial."
    },
    classification: {
      type: "string",
      description:
        "Classificação da intenção do cliente. Deve ser igual ao valor de 'fluxo'."
    },
    acoes_banco_dados: {
      type: "array",
      description:
        "Lista de operações de banco de dados. Neste agente, normalmente vazio [].",
      items: {
        type: "object",
        properties: {
          operacao: { type: "string" },
          dados: { type: "object" }
        }
      }
    },
    followup: {
      type: "object",
      description:
        "Configuração de follow-up automático. Neste agente, normalmente needs_followup = false.",
      properties: {
        needs_followup: {
          type: "boolean",
          description:
            "Se true, indica que deve haver um follow-up automático. Padrão: false."
        },
        topic: {
          type: "string",
          description:
            "Resumo curto do motivo do follow-up, se existir. Normalmente vazio."
        },
        timeout_minutes: {
          type: "number",
          description:
            "Tempo em minutos até o follow-up. Normalmente 0 neste agente."
        }
      }
    }
  }
};

// ============================================================================
// FUNÇÃO PRINCIPAL DE INTEGRAÇÃO COM O FLUXO (USADA PELO n8n)
// ============================================================================

function buildCompletePayload({
  userMessage,
  isFirstTurn,
  hasProject,
  bkInput,
  maxChars,
  currentStep,
  conversationHistory,
  customerData,
  projectData,
  assistantName = "Sophia - Atendimento Inicial",
  modelHint = "gpt-4.1-mini",
  llm_payload_in = {}
}) {
  // Constrói o prompt dinâmico para o atendimento inicial
  const prompt = buildDynamicPrompt({
    userMessage,
    isFirstTurn,
    hasProjectFlag: hasProject,
    bkQuestions: bkInput,
    maxChars,
    currentStep,
    conversationHistory,
    customerData,
    projectData
  });

  // Metadados para tracking
  const meta = {
    assistant_name: assistantName,
    first_turn: isFirstTurn,
    has_project_flag: hasProject,
    current_step: currentStep,
    project_id: projectData?.project_id ?? null,
    chat_id: customerData?.chat_id ?? null,
    customer_phone: customerData?.phone ?? null,
    max_chars: maxChars,
    model_hint: modelHint,
    timestamp: new Date().toISOString()
  };

  // Preferências do LLM
  const llm_prefs = {
    model: modelHint,
    temperature: 0.6,
    max_tokens: Math.ceil(maxChars * 1.5),
    response_format: { type: "json_object" }
  };

  // Payload unificado para o nó LLM
  const llm_payload = {
    ...llm_payload_in,
    ...llm_prefs,
    messages: [
      {
        role: "user",
        content: JSON.stringify(prompt, null, 2)
      }
    ]
  };

  // Retorno no formato esperado pelo n8n: array de objetos { json: ... }
  return [
    {
      json: {
        llm_prefs,
        prompt: JSON.stringify(prompt),
        schema: RESPONSE_SCHEMA,
        meta,
        llm_payload,
        raw_data: {
          userMessage,
          isFirstTurn,
          hasProject,
          currentStep,
          customerData,
          projectData
        }
      }
    }
  ];
}

// ============================================================================
// MAPEAMENTO DOS DADOS DE ENTRADA DO ITEM (N8N)
// ============================================================================

const userMessage = String(
  $json.llm_payload?.message?.content ??
    $json.userMessage ??
    $json.message ??
    $json.text ??
    $json.payload?.message ??
    ""
).trim();

const isFirstTurn = Boolean(
  $json.isFirstTurn ?? $json.flags?.is_first_turn ?? false
);

const hasProject = Boolean(
  $json.hasProject ?? $json.payload?.project_id ?? false
);

const bkInput = Array.isArray($json.bk_questions)
  ? $json.bk_questions
  : [];

const maxChars = Number.isFinite($json.max_chars) ? $json.max_chars : 400;

const currentStep = $json.current_step || "atendimento_inicial";

const conversationHistory = Array.isArray($json.conversation_history)
  ? $json.conversation_history
  : [];

const customerData = $json.customerData ?? $json.customer ?? {};

const projectData = $json.projectData ?? $json.project ?? null;

const assistantName = "Sophia - Atendimento Inicial";

const modelHint = $json.model_hint ?? "gpt-4.1-mini";

const llm_payload_in = $json.llm_payload ?? {};

// Chama a função principal e retorna para o n8n
return buildCompletePayload({
  userMessage,
  isFirstTurn,
  hasProject,
  bkInput,
  maxChars,
  currentStep,
  conversationHistory,
  customerData,
  projectData,
  assistantName,
  modelHint,
  llm_payload_in
});

// Pega a string crua vinda do agente
const raw = $json.output || "";

// Remove blocos ```json e ```
const cleaned = raw
  .replace(/```json/gi, "")
  .replace(/```/g, "")
  .trim();

// Faz o parse para objeto
let parsed;
try {
  parsed = JSON.parse(cleaned);
} catch (e) {
  throw new Error("Falha ao fazer parse do JSON de saída da IA: " + e.message);
}

// Retorna no formato n8n
return [
  {
    json: parsed
  }
];

// 1. Resolver os dados necessários do item

// A mensagem original do cliente vem da IA como "mensagem_cliente"
const userMessage =
  $json.mensagem_cliente ??
  $json.userMessage ??
  ($json.llm_payload &&
    $json.llm_payload.message &&
    $json.llm_payload.message.content) ??
  "";

// A resposta da IA vem em "reply"
const aiText = $json.reply ?? "";

// O session_id (id do chat) vem de llm_payload.chat.id
const sessionId =
  ($json.llm_payload &&
    $json.llm_payload.chat &&
    $json.llm_payload.chat.id) ||
  $json.session_id ||
  null;

if (!sessionId) {
  throw new Error(
    "sessionId não encontrado. Esperado em llm_payload.chat.id ou session_id."
  );
}

// 2. Criar o item para a mensagem do Cliente (Human)
const humanMessage = {
  json: {
    session_id: sessionId,
    message: JSON.stringify({
      type: "human",
      content: userMessage,
      timestamp: new Date().toISOString(),
      step: "atendimento_inicial"
    })
  }
};

// 3. Criar o item para a resposta da Sophia (AI)
const aiMessage = {
  json: {
    session_id: sessionId,
    message: JSON.stringify({
      type: "ai",
      content: aiText,
      timestamp: new Date().toISOString(),
      step: "atendimento_inicial"
    })
  }
};

// 4. Retornar os dois itens para o nó Postgres
return [humanMessage, aiMessage];

// ============================================================================
// SOURCE FOR PROMPT (USER MESSAGE) - AGENTE SOPHIA (QUALIFICAÇÃO)
// ============================================================================

/**
 * Função principal para construir o prompt dinâmico baseado no contexto
 * (Agente 2 - Qualificação)
 */
function buildDynamicPrompt({
  userMessage,
  isFirstTurn,
  maxChars,
  conversationHistory = [],
  customerData = {},
  currentStep = "qualificacao"
}) {
  const promptSections = [];

  // ================================================================
  // 1 — CONTEXTO ATUAL DA QUALIFICAÇÃO
  // ================================================================
  promptSections.push({
    section: "CONTEXTO_ATUAL",
    data: {
      etapa: "QUALIFICACAO",
      turno: isFirstTurn ? "PRIMEIRA_MENSAGEM_NA_QUALIFICACAO" : "QUALIFICACAO_EM_ANDAMENTO",
      mensagem_usuario: userMessage,
      limite_caracteres: maxChars
    },
    instruction: `
      Você é a AGENTE DE QUALIFICAÇÃO.

      O cliente já passou pelo atendimento inicial e foi identificado como alguém que:
      - quer iniciar um novo projeto / orçamento, e
      - agora precisa responder às perguntas de qualificação.

      Seu foco é:
      1. Coletar os dados mínimos para o time da loja avaliar o projeto.
      2. Fazer perguntas claras, diretas e educadas.
      3. Salvar cada dado coletado imediatamente nas ações de banco de dados.
      4. Não repetir perguntas já respondidas no histórico.
      5. Não fazer triagem de fluxo nem localizar projeto.
    `.trim()
  });

  // ================================================================
  // 2 — HISTÓRICO E DADOS DO CLIENTE (SE HOUVER)
  // ================================================================
  if (conversationHistory.length > 0 || Object.keys(customerData).length > 0) {
    promptSections.push({
      section: "HISTORICO_CLIENTE",
      data: {
        historico_mensagens: conversationHistory.slice(-10),
        dados_cliente: {
          nome: customerData.name || null,
          telefone: customerData.phone || null,
          email: customerData.email || null,
          qualificacao_existente: customerData.qualification_data || {}
        }
      },
      instruction: `
        Use o histórico e os dados já salvos para NÃO repetir perguntas.

        Regras:
        1. Se o nome completo já estiver claramente registrado, não peça novamente.
        2. Se o telefone já estiver preenchido em formato válido, não peça novamente.
        3. Se o histórico mostrar que o cliente já informou ambiente, finalidade ou tipo de imóvel, não repita.
        4. Sempre que possível, confirme informações ao invés de perguntar do zero.
      `.trim()
    });
  }

  // ================================================================
  // 3 — CAMPOS DE QUALIFICAÇÃO OBRIGATÓRIOS
  // ================================================================
  promptSections.push({
    section: "CAMPOS_QUALIFICACAO",
    data: {
      campos_obrigatorios: [
        "nome_completo",
        "telefone",
        "ambiente",
        "finalidade_projeto",
        "tipo_imovel"
      ],
      descricao_campos: {
        nome_completo: "Nome completo do titular do projeto.",
        telefone: "Telefone de melhor contato, no formato (DDD) 9XXXX-XXXX.",
        ambiente: "Ambiente principal a ser planejado (cozinha, suíte, sala, varanda etc.).",
        finalidade_projeto: "Motivo principal do projeto (morar, alugar, vender, outro).",
        tipo_imovel: "Tipo de imóvel (casa, apartamento, comercial, outro)."
      }
    },
    instruction: `
      Estes são os campos que você precisa coletar durante a qualificação:

      1) nome_completo
      2) telefone (formato (DDD) 9XXXX-XXXX)
      3) ambiente
      4) finalidade_projeto (morar, alugar, vender, outro)
      5) tipo_imovel (casa, apartamento, comercial, outro)

      Você deve sempre:
      - Marcar quais campos já foram preenchidos.
      - Saber quais ainda faltam.
      - Avançar para a próxima pergunta apenas quando tiver uma resposta válida.
    `.trim()
  });

  // ================================================================
  // 4 — ESTRATÉGIA DE PERGUNTAS
  // ================================================================
  promptSections.push({
    section: "ESTRATEGIA_PERGUNTAS",
    instruction: `
      ORDEM E FORMA DAS PERGUNTAS:

      1) PRIMEIRA PERGUNTA (NA QUALIFICAÇÃO):
         - Peça NOME COMPLETO e TELEFONE na mesma mensagem.
         Exemplo:
         "Perfeito! Para começarmos, você pode me informar o NOME COMPLETO do titular do projeto e
         o telefone de melhor contato, nesse formato: (DDD) 9XXXX-XXXX?"

         Regras:
         - Se o cliente responder apenas um dos dois (só nome ou só telefone), faça uma resposta curta
           agradecendo e peça especificamente o dado que faltou.
         - Valide que o nome parece completo (ao menos nome e sobrenome).
         - Valide o telefone no formato brasileiro com DDD + 9 + número.

      2) DEPOIS DE TER NOME E TELEFONE:
         Faça as perguntas restantes, uma por vez, na ordem:

         a) Ambiente:
            "Qual ambiente você deseja planejar? (Ex.: cozinha, suíte, sala, varanda, etc.)"

         b) Finalidade do projeto:
            "Esse projeto é para morar, alugar, vender ou outro motivo?"

         c) Tipo de imóvel:
            "O imóvel é uma casa, apartamento, comercial ou outro tipo de imóvel?"

      3) CONDUTA DURANTE A QUALIFICAÇÃO:
         - Sempre confirme rapidamente o que o cliente respondeu ("Perfeito, obrigado!").
         - Não envie perguntas gigantes com tudo de uma vez.
         - Uma mensagem = no máximo uma nova pergunta (exceto no caso inicial de nome + telefone).
         - Seja sempre educada e deixe claro que isso ajuda a montar um orçamento mais preciso.
    `.trim()
  });

  // ================================================================
  // 5 — REGRAS DE VALIDAÇÃO
  // ================================================================
  promptSections.push({
    section: "REGRAS_VALIDACAO",
    instruction: `
