// 1) Pega a saída crua do AI Agent
// No seu caso ela veio em $json.output como string JSON.
// Mas deixei fallback pra outros formatos.
const raw =
  $json.output ??
  $json.aiResponse ??
  $json.response ??
  $json.text ??
  $json;

// 2) Se já veio como objeto (não-string), só retorna
if (raw && typeof raw === "object" && !Array.isArray(raw)) {
  return [{ json: raw }];
}

// 3) Se veio array com objeto dentro, retorna o primeiro
if (Array.isArray(raw) && raw.length > 0 && typeof raw[0] === "object") {
  return [{ json: raw[0] }];
}

// 4) Agora tratamos como string
const rawStr = String(raw || "").trim();

// Remove blocos markdown se existirem
const cleaned = rawStr
  .replace(/```json/gi, "")
  .replace(/```/g, "")
  .trim();

// 5) Parse do JSON
let parsed;
try {
  parsed = JSON.parse(cleaned);
} catch (e) {
  throw new Error(
    "Falha ao fazer parse do JSON da Qualificação. Saída recebida:\n" +
      cleaned +
      "\n\nErro: " +
      e.message
  );
}

// 6) Retorna no formato que o n8n espera
return [{ json: parsed }];

