function buildDynamicPrompt({
  userMessage,
  isFirstTurn,
  hasProjectFlag,
  maxChars,
  currentStep,
  conversationHistory = [],
  customerData = {},
  projectData = null
}) {
  const promptSections = [];

  // ========================================================================
