  userMessage,
  isFirstTurn,
  hasProject,
  maxChars,
  currentStep,
  conversationHistory,
  customerData,
  projectData,
  assistantName = "Sophia",
  modelHint = "gpt-4.1-mini",
  llm_payload_in = {}
}) {
  const prompt = buildDynamicPrompt({
    userMessage,
    isFirstTurn,
    hasProjectFlag: hasProject,
    maxChars,
    currentStep,
    conversationHistory,
    customerData,
    projectData
  });

