// ============================================================================

const userMessage = String(
  $json.llm_payload?.message?.content ??
    $json.userMessage ??
    $json.message ??
    $json.text ??
    $json.payload?.message ??
    ""
).trim();

const isFirstTurn = Boolean(
  $json.isFirstTurn ?? $json.flags?.is_first_turn ?? false
);

const hasProject = Boolean(
  $json.hasProject ?? $json.payload?.project_id ?? false
);

const bkInput = Array.isArray($json.bk_questions)
  ? $json.bk_questions
  : [];

const maxChars = Number.isFinite($json.max_chars) ? $json.max_chars : 400;

const currentStep = $json.current_step || "atendimento_inicial";

const conversationHistory = Array.isArray($json.conversation_history)
  ? $json.conversation_history
  : [];

const customerData = $json.customerData ?? $json.customer ?? {};

const projectData = $json.projectData ?? $json.project ?? null;

const assistantName = "Sophia - Atendimento Inicial";

const modelHint = $json.model_hint ?? "gpt-4.1-mini";

const llm_payload_in = $json.llm_payload ?? {};

// Chama a função principal e retorna para o n8n
return buildCompletePayload({
  userMessage,
  isFirstTurn,
  hasProject,
  bkInput,
  maxChars,
  currentStep,
  conversationHistory,
  customerData,
  projectData,
  assistantName,
  modelHint,
  llm_payload_in
});

const ctx = $json.context ?? {};
const msg = $json.message ?? {};

const ensure = (cond, message, statusCode = 400) => {
  if (!cond) {
    const e = new Error(message); e.statusCode = statusCode; throw e;
  }
};

// Campos básicos vindos do contexto
const chat_id    = ctx.chat_id    ?? null;
const project_id = ctx.project_id ?? null;
const timestamp  = ctx.timestamp  ?? new Date().toISOString();
const user_id    = ctx.customer_phone ?? null; // usamos o phone como id de usuário final
const user_name  = ctx.customer_name ?? null;

ensure(chat_id && project_id, 'Unificar: context.chat_id e context.project_id são obrigatórios.');
ensure(msg && typeof msg === 'object', 'Unificar: message ausente.');

// Mapeia por tipo
const type = msg.type;
ensure(typeof type === 'string', 'Unificar: message.type ausente.');

let message_content = null;   // texto ou conteúdo primário
let caption = null;
let attachments = [];         // lista genérica (url/mime/filename/size/sha256/..)
let duration_seconds = null;  // para áudio/vídeo
let location = null;          // para location
let contacts = null;          // para contact
let template = null;          // para template
let direction = msg.direction ?? 'inbound';

// Normaliza por tipo
switch (type) {
  case 'text': {
    ensure(typeof msg.text === 'string', 'Unificar: message.text obrigatório para type=text.');
    message_content = msg.text;
    break;
  }
  case 'image': {
    const images = Array.isArray(msg.images) ? msg.images : [];
    ensure(images.length > 0, 'Unificar: images vazio para type=image.');
    message_content = images[0].url;
    caption = images[0].caption ?? null;
    attachments = images.map(i => ({
      kind: 'image',
      url: i.url,
      mime_type: i.mime_type,
      filename: i.filename,
      extension: i.extension ?? null,
      size_bytes: i.size_bytes ?? null,
      sha256: i.sha256 ?? null,
      index: i.index ?? null
    }));
    break;
  }
  case 'audio': {
    const audios = Array.isArray(msg.audios) ? msg.audios : [];
    ensure(audios.length > 0, 'Unificar: audios vazio para type=audio.');
    message_content = audios[0].url;
    duration_seconds = audios[0].duration_seconds ?? null;
    attachments = audios.map(a => ({
      kind: 'audio',
      url: a.url,
      mime_type: a.mime_type,
      filename: a.filename,
      extension: a.extension ?? null,
      size_bytes: a.size_bytes ?? null,
      sha256: a.sha256 ?? null,
      index: a.index ?? null
    }));
    break;
  }
  case 'document': {
    const docs = Array.isArray(msg.documents) ? msg.documents : [];
    ensure(docs.length > 0, 'Unificar: documents vazio para type=document.');
    message_content = docs[0].url;
    caption = docs[0].caption ?? null;
    attachments = docs.map(d => ({
      kind: 'document',
      url: d.url,
      mime_type: d.mime_type,
      filename: d.filename,
      extension: d.extension ?? null,
      size_bytes: d.size_bytes ?? null,
      sha256: d.sha256 ?? null,
      index: d.index ?? null
    }));
    break;
  }
  case 'video': {
    const vids = Array.isArray(msg.videos) ? msg.videos : [];
    ensure(vids.length > 0, 'Unificar: videos vazio para type=video.');
    message_content = vids[0].url;
    caption = vids[0].caption ?? null;
    duration_seconds = vids[0].duration_seconds ?? null;
    attachments = vids.map(v => ({
      kind: 'video',
      url: v.url,
      mime_type: v.mime_type,
      filename: v.filename,
      extension: v.extension ?? null,
      size_bytes: v.size_bytes ?? null,
      sha256: v.sha256 ?? null,
      index: v.index ?? null
    }));
    break;
  }
  case 'sticker': {
    const stickers = Array.isArray(msg.stickers) ? msg.stickers : [];
    ensure(stickers.length > 0, 'Unificar: stickers vazio para type=sticker.');
    message_content = stickers[0].url;
    attachments = stickers.map(s => ({
      kind: 'sticker',
      url: s.url,
      mime_type: s.mime_type,
      filename: s.filename,
      extension: s.extension ?? null,
      size_bytes: s.size_bytes ?? null,
      sha256: s.sha256 ?? null,
      index: s.index ?? null
    }));
    break;
  }
  case 'location': {
    ensure(msg.location && typeof msg.location === 'object', 'Unificar: location ausente para type=location.');
    location = {
      latitude: msg.location.latitude,
      longitude: msg.location.longitude,
      address: msg.location.address ?? null,
      name: msg.location.name ?? null
    };
    message_content = `${location.latitude},${location.longitude}`;
    break;
  }
  case 'contact': {
    const list = Array.isArray(msg.contacts) ? msg.contacts : [];
    ensure(list.length > 0, 'Unificar: contacts vazio para type=contact.');
    contacts = list.map(c => ({
      phone: c.phone,
      name: c.name ?? null,
      org: c.org ?? null,
      vcard: c.vcard ?? null,
      index: c.index ?? null
    }));
    message_content = `${contacts[0].name ?? 'Contato'} (${contacts[0].phone})`;
    break;
  }
  case 'template': {
    ensure(msg.template && typeof msg.template === 'object', 'Unificar: template ausente para type=template.');
    template = {
      name: msg.template.name,
      namespace: msg.template.namespace ?? null,
      language: msg.template.language ?? null,
      components: msg.template.components ?? null
    };
    message_content = template.name;
    break;
  }
  default: {
    const e = new Error(`Unificar: tipo não suportado (${type}).`);
    e.statusCode = 415; throw e;
  }
}

// ---------- Política de tamanho de resposta (para Model Selector) ----------
// Regra de negócio (padrão): mídia/ações rápidas → curto; restante → longo
const isMedia = ['image','audio','document','video','sticker','location','contact','template'].includes(type);
const wantsShort =
  isMedia ||
  ctx.reply_style === 'short' ||
  (ctx.meta && ctx.meta.force_short === true);

// Permite override vindo de upstream ($json.llm_prefs?.max_chars)
const incomingMax = $json.llm_prefs?.max_chars;
const maxChars = Number.isFinite(incomingMax) ? incomingMax : (wantsShort ? 70 : 400);
const modelHint = maxChars <= 70 ? 'short' : 'long';

const llm_prefs = {
  max_chars: maxChars,
  model_hint: modelHint
};
// --------------------------------------------------------------------------

// Monta o payload padronizado para a IA
const unified = {
  user_id,
  user_name,
  message_type: type,
  message_content,
  chat_id,
  project_id,
  timestamp,
  caption,

  direction,
  attachments,
  duration_seconds,
  location,
  contacts,
  template,

  event_id: ctx.event_id ?? null,
  channel: ctx.channel ?? null,
  ia_user_id: ctx.ia_user_id ?? null,

  // útil se alguém consumir do unified
  llm_prefs
};

// bloco prontinho para LLM 
const llm_payload = {
  chat: {
    id: chat_id,
    project_id,
    channel: ctx.channel,
    timestamp,
  },
  user: {
    id: user_id,
    name: user_name
  },
  message: {
    type,
    content: message_content,
    caption,
    attachments,
    duration_seconds,
    location,
    contacts,
    template
  },
  hints: {
    is_media: isMedia,
    is_text: type === 'text',
    has_location: !!location,
    has_contacts: Array.isArray(contacts) && contacts.length > 0
  },
  llm_prefs // também dentro do bloco da LLM
};

return [{
  json: {
    // expõe no item raiz para o Model Selector ler: $json.llm_prefs.max_chars
    llm_prefs,
    unified,
    llm_payload
  }
}];

// Code - Reanexar Contexto (após PUT Atendimento Inicial)

// Resposta do PUT (o que veio do CLIENT_APP)
const putResp = $json;

// Payload completo original (antes do PUT)
const original = $node["Merge - Combinação JWT e AI7"].json;

// Junta tudo: mantém o contexto e guarda a resposta do PUT separado
return [
  {
    json: {
      ...original,              // classification, fluxo, llm_payload, token, etc
      put_atendimento: putResp  // opcional: pra debug/log
    }
  }
];

// Code – Gate de Etapa (SEM nó Merge, com 2 inputs)

// Pega todos os inputs conectados no Code node
const inputs = $input.all().map(i => i.json);

// Acha o payload original (tem llm_payload/unified)
const original = inputs.find(i => i.llm_payload || i.unified) || {};

// Acha a linha do Postgres (tem "message" e "session_id" simples)
const pgRow = inputs.find(i => i.message && i.session_id && !i.llm_payload) || null;

// Extrai step do Postgres
let lastStep = null;
if (pgRow) {
  try {
    const msg = typeof pgRow.message === "string"
      ? JSON.parse(pgRow.message)
      : pgRow.message;
    lastStep = msg?.step || null;
  } catch (e) {
    lastStep = null;
  }
}

// Define skip
const skip = ["qualificacao", "localizacao_projeto"].includes(lastStep);

// Retorna payload completo + flags
return [{
  json: {
    ...original,
    last_step: lastStep,
    skip_agent1: skip
  }
}];

// Code – Reset Session (Localização)

const item = $json;

const chatId = item.llm_payload?.chat?.id || item.session_id || item.chat_id;

const newSessionId = `${chatId}-localizacao-${Date.now()}`;

item.session_id = newSessionId;
item.current_step = "localizacao_projeto";

item.session_origin = {
  base_chat_id: chatId,
  step: "localizacao_projeto",
  created_at: new Date().toISOString()
};

return [{ json: item }];

// Code – Reset Session (Qualificação)

const item = $json;

// mantém o chat real
const chatId = item.llm_payload?.chat?.id || item.session_id || item.chat_id;

// cria novo session_id exclusivo dessa etapa
const newSessionId = `${chatId}-qualificacao-${Date.now()}`;

item.session_id = newSessionId;
item.current_step = "qualificacao";

// opcional: marcar origem pra debug
item.session_origin = {
  base_chat_id: chatId,
  step: "qualificacao",
  created_at: new Date().toISOString()
};

return [{ json: item }];

// Code – Histórico (localizacao_projeto)

// 1. Resolver dados do item

// Mensagem original do cliente
const userMessage =
  $json.mensagem_cliente ??
  $json.userMessage ??
  "";

// Mensagem da IA
const aiText = $json.reply ?? "";

// session_id (id do chat)
const sessionId =
  ($json.llm_payload &&
    $json.llm_payload.chat &&
    $json.llm_payload.chat.id) ||
  $json.session_id ||
  null;

if (!sessionId) {
  throw new Error(
    "sessionId não encontrado. Esperado em llm_payload.chat.id ou session_id."
  );
}

// 2. Criar mensagem do cliente (Human)
const humanMessage = {
  json: {
    session_id: sessionId,
    message: JSON.stringify({
      type: "human",
      content: userMessage,
      timestamp: new Date().toISOString(),
      step: "localizacao_projeto"
    })
  }
};

// 3. Criar mensagem da Sophia (AI)
const aiMessage = {
  json: {
    session_id: sessionId,
    message: JSON.stringify({
      type: "ai",
      content: aiText,
      timestamp: new Date().toISOString(),
      step: "localizacao_projeto"
    })
  }
};

// 4. Retornar os dois itens para Postgres (insert múltiplo)
return [humanMessage, aiMessage];

// Code – Ajuste output AI (Localização)

// 1) Pega a saída crua do AI Agent
// Geralmente vem em $json.output como string JSON
// Mas deixei fallback pra segurança
const raw =
  $json.output ??
  $json.aiResponse ??
  $json.response ??
  $json.text ??
  $json;

// 2) Se já veio como objeto JSON, só retorna
if (raw && typeof raw === "object" && !Array.isArray(raw)) {
  return [{ json: raw }];
}

// 3) Se for array com objeto dentro -> retorna o primeiro item
if (Array.isArray(raw) && raw.length > 0 && typeof raw[0] === "object") {
  return [{ json: raw[0] }];
}

// 4) Agora tratamos como string
const rawStr = String(raw || "").trim();

// Remove markdown ```json ou ``` se houver
const cleaned = rawStr
  .replace(/```json/gi, "")
  .replace(/```/g, "")
  .trim();

// 5) Tentar fazer parse do JSON
let parsed;
try {
  parsed = JSON.parse(cleaned);
} catch (e) {
  throw new Error(
    "Falha ao fazer parse do JSON retornado pela AI (localização). Saída recebida:\n\n" +
      cleaned +
      "\n\nErro: " +
      e.message
  );
}

// 6) Retorna no formato padrão do n8n
return [{ json: parsed }];

// Este Tool recebe os dados de UM projeto na variável "query".
// "query" pode vir como string JSON ou como objeto; tratamos os dois casos.
// O retorno SEMPRE será uma string JSON contendo a propriedade "projectData".

function toObject(input) {
  if (input === null || input === undefined) return null;
  if (typeof input === 'object') return input;
  try {
    return JSON.parse(String(input));
  } catch {
    return null;
  }
}

function resposta(obj) {
  return JSON.stringify(obj, null, 2);
}

// Converte a entrada em objeto
const projeto = toObject(query);

if (!projeto || typeof projeto !== 'object') {
  return resposta({
    ok: false,
    reason: "INVALID_PROJECT_INPUT",
    projectData: null
  });
}

// Tentamos ser tolerantes a diferentes nomes de campos
const projectData = {
  project_id:      projeto.id ?? projeto.project_id ?? null,
  project_number:  projeto.number ?? projeto.project_number ?? null,
  owner_name:      projeto.owner_name ?? projeto.titular ?? projeto.client_name ?? null,
  project_type:    projeto.project_type ?? projeto.type ?? null,
  status:          projeto.status ?? null,
  assigned_to:     projeto.assigned_to ?? projeto.responsible ?? projeto.responsavel_humano ?? null,
  created_at:      projeto.created_at ?? null,
  updated_at:      projeto.updated_at ?? null,

  // Campos extras úteis, se existirem
  step:            projeto.step ?? projeto.current_step ?? null,
  store_name:      projeto.store_name ?? projeto.loja ?? null
};

return resposta({
  ok: true,
  projectData
});

// "query" sempre contém a entrada enviada pelo agente.
// Neste caso: a lista de projetos retornada pela API /projects.
const projetos = query;

function resposta(obj) {
  return JSON.stringify(obj, null, 2);
}

// Se não veio array ou está vazio
if (!Array.isArray(projetos) || projetos.length === 0) {
  return resposta({
    found: false,
    reason: "NO_PROJECTS_FOUND",
    project_id: null,
    project: null
  });
}

// Se houver só um projeto, retorna direto
if (projetos.length === 1) {
  const p = projetos[0];
  return resposta({
    found: true,
    project_id: p.id,
    project: p
  });
}

// Se houver vários projetos, escolher o mais atualizado (updated_at mais recente)
projetos.sort((a, b) => {
  const da = new Date(a.updated_at ?? a.created_at ?? 0);
  const db = new Date(b.updated_at ?? b.created_at ?? 0);
  return db - da; // ordem desc
});

const selecionado = projetos[0];

// Retorna projeto selecionado e id
return resposta({
  found: true,
  project_id: selecionado.id,
  project: selecionado
});

// ============================================================================
// Function — Build LLM Prompt (Localizacao do Projeto)
// AGENTE 3: LOCALIZAÇÃO DE PROJETO (versão para n8n Function)
// ============================================================================

/**
 * Constrói prompt dinâmico focado APENAS em localizar projeto existente.
 */
function buildDynamicPrompt({
  userMessage,
  isFirstTurn,
  hasProjectFlag,
  maxChars,
  currentStep,
  conversationHistory = [],
  customerData = {},
  projectData = null
}) {
  const promptSections = [];

  // ========================================================================
  // SEÇÃO 1: CONTEXTO ATUAL
  // ========================================================================
  promptSections.push({
    section: "CONTEXT",
    data: {
      turno: isFirstTurn ? "PRIMEIRO_CONTATO" : "CONVERSA_EM_ANDAMENTO",
      mensagem_usuario: userMessage,
      historico: conversationHistory.slice(-10),
      dados_cliente: customerData,
      cliente_tem_projeto_sinalizado: hasProjectFlag,
      etapa_atual_fluxo: currentStep || "localizacao_projeto",
      limite_caracteres: maxChars
    },
    instruction: `
Você é a AGENTE DE LOCALIZAÇÃO DE PROJETO.

Seu papel é APENAS:
1. Entender se o cliente quer falar de um projeto em andamento.
2. Coletar dados mínimos para localizar o projeto.
3. Usar as ferramentas do CLIENT_APP para encontrar o projeto correto.
4. Confirmar com o cliente o projeto encontrado.
5. Se não localizar, pedir novos dados ou transferir para humano.

Você NÃO deve:
- Fazer perguntas de qualificação de lead novo.
- Oferecer orçamento ou iniciar novos projetos.
- Inventar informações sobre projeto.
- Usar ferramentas sem dados suficientes.
    `.trim()
  });

  // ========================================================================
  // SEÇÃO 2: SE JÁ TEMOS UM projectData PRONTO
  // ========================================================================
  if (hasProjectFlag && projectData) {
    promptSections.push({
      section: "PROJETO_JA_IDENTIFICADO",
      data: {
        projeto: projectData
      },
      instruction: `
Já existe um projeto identificado no contexto do sistema.
AÇÕES:
- Confirme o projeto com o cliente citando número/titular.
- Pergunte qual é a dúvida específica dele sobre ESTE projeto.
- Não refaça coleta de dados de localização.
      `.trim()
    });
  }

  // ========================================================================
  // SEÇÃO 3: REGRAS PARA COLETA DE DADOS
  // ========================================================================
  promptSections.push({
    section: "COLETA_DADOS_LOCALIZACAO",
    data: {
      dados_validos: [
        "numero_projeto",
        "nome_completo_titular",
        "telefone_cadastrado",
        "cpf_cnpj"
      ],
      regra_nome: "NUNCA buscar só com primeiro nome"
    },
    instruction: `
Para localizar um projeto você PRECISA de pelo menos UM dado confiável:

- Número do projeto, OU
- Nome completo do titular (nome + sobrenome), OU
- Telefone cadastrado, OU
- CPF/CNPJ.

Se o cliente não souber o número:
1) Pergunte se ele é o titular do projeto.
2) Se NÃO for titular (ex.: “projeto da minha esposa / marido / mãe / cliente”):
   - Peça o NOME COMPLETO do titular e/ou o TELEFONE dele.
3) Se o cliente informar só o primeiro nome do titular:
   - Peça educadamente o nome completo ANTES de buscar.
4) Não siga para ferramentas até ter um dado válido.

Exemplo correto:
"Para eu localizar certinho aqui, pode me informar o número do projeto? 
Se não tiver, me passe o nome completo do titular ou o telefone cadastrado, por favor."
    `.trim()
  });

  // ========================================================================
  // SEÇÃO 4: FERRAMENTAS DISPONÍVEIS
  // ========================================================================
  promptSections.push({
    section: "FERRAMENTAS_CLIENT_APP",
    data: {
      ferramentas: [
        {
          nome: "lista_projetos",
          tipo: "http",
          quando_usar: "Quando tiver número, telefone, CPF/CNPJ ou nome completo"
        },
        {
          nome: "selecionar_projeto",
          tipo: "code",
          quando_usar: "Após receber lista_projetos"
        },
        {
          nome: "projeto_id",
          tipo: "http",
          quando_usar: "Quando precisar detalhes do projeto escolhido"
        },
        {
          nome: "preparar_projectdata",
          tipo: "code",
          quando_usar: "Para padronizar dados do projeto antes de responder"
        }
      ]
    },
    instruction: `
USO DAS FERRAMENTAS (ordem obrigatória):

1) Quando tiver ao menos UM dado válido:
   - Chame "lista_projetos" com filtros:
     {"project_number": "..."} ou {"phone": "..."} ou {"cpf_cnpj": "..."} ou {"owner_name": "..."}.

2) Pegue a lista retornada e chame "selecionar_projeto" para escolher o projeto mais provável.

3) Se precisar de detalhes, chame "projeto_id" com o project_id selecionado.

4) Depois chame "preparar_projectdata" para criar um projectData padronizado.

5) Responda ao cliente confirmando:
   "Localizei o projeto X em nome de Y. É sobre ele que você quer falar?"

6) Se lista_projetos voltar vazia:
   - Informe que não localizou com aqueles dados
   - peça outro dado válido
   - ou ofereça transferência para humano.

Regras críticas:
- Nunca chame ferramenta com primeiro nome apenas.
- Nunca invente status/etapa.
    `.trim()
  });

  // ========================================================================
  // SEÇÃO 5: REGRAS DE OUTPUT / JSON
  // ========================================================================
  promptSections.push({
    section: "RESPONSE_RULES",
    instruction: `
Você DEVE responder SOMENTE em JSON válido, com estes campos:

{
  "reply": "mensagem que será enviada ao cliente",
  "mensagem_cliente": "mensagem original do cliente, sem alteração",
  "fluxo": "localizacao_projeto",
  "classification": "localizacao_projeto",
  "dados_localizacao": {
    "numero_projeto": null|string,
    "nome_completo_titular": null|string,
    "telefone_cadastrado": null|string,
    "cpf_cnpj": null|string,
    "titular_confirmado": null|boolean,
    "campos_preenchidos": [],
    "campos_pendentes": []
  },
  "status_localizacao": "aguardando_dados | buscando | encontrado | nao_encontrado | transferir_humano",
  "proxima_pergunta": null|string,
  "projectData": null|object,
  "acoes_banco_dados": [
    {
      "operacao": "SALVAR_MENSAGEM",
      "dados": {
        "mensagem_cliente": "<mensagem_original_do_cliente>",
        "mensagem_ia": "<reply>"
      }
    }
  ],
  "followup": {
    "needs_followup": false,
    "topic": "",
    "timeout_minutes": 0
  }
}

Regras:
- "reply" é OBRIGATÓRIO e nunca pode ser vazio.
- "mensagem_cliente" deve ser exatamente o texto do cliente.
- Se estiver pedindo dados, use status_localizacao="aguardando_dados" e proxima_pergunta com a pergunta.
- Só use followup.needs_followup=true se:
  (a) já teve dados válidos,
  (b) já usou TODAS as ferramentas,
  (c) e mesmo assim não localizou.
    `.trim()
  });

  // ========================================================================
  // MONTAGEM FINAL DO PROMPT
  // ========================================================================
  const finalPrompt = {
    prompt_version: "1.0-localizacao-projeto",
    timestamp: new Date().toISOString(),
    sections: promptSections,
    user_message: userMessage,
    response_requirements: {
      format:
        "JSON puro, sem markdown, sem ```json, sem texto fora do JSON.",
      max_length: maxChars,
      tone: "amigável, direto e profissional",
      mandatory_fields: [
        "reply",
        "mensagem_cliente",
        "fluxo",
        "classification",
        "dados_localizacao",
        "status_localizacao",
        "proxima_pergunta",
        "projectData",
        "acoes_banco_dados",
        "followup"
      ]
    }
  };

  return finalPrompt;
}

