/**
 * ============================================================================
 * Code Node — Decisão de Transferência de Etapa (Qualificação)
 * ============================================================================
 * Responsabilidade:
 * - Extrair contexto fixo (project_id, chat_id, store_id, etc)
 * - Extrair JWT do usuário (obrigatório para chamadas autenticadas)
 * - Identificar intenção da IA de transferir etapa
 * - Normalizar decisão em flags claras para o fluxo
 * ============================================================================
 */

const input = $json ?? {};

// ---------------------------------------------------------------------------
// 1️⃣ EXTRAÇÃO DE CONTEXTO FIXO
// ---------------------------------------------------------------------------
const context = {
  project_id: input.project_id ?? input.context?.project_id ?? null,
  chat_id: input.chat_id ?? input.context?.chat_id ?? null,
  store_id: input.store_id ?? input.context?.store_id ?? null,
  channel: input.channel ?? input.context?.channel ?? null,
  ia_user_id: input.ia_user_id ?? input.context?.ia_user_id ?? null,
};

// ---------------------------------------------------------------------------
// 2️⃣ EXTRAÇÃO DO TOKEN JWT (CRÍTICO)
// ---------------------------------------------------------------------------
const jwt =
  input.token?.jwt ??
  input.jwt ??
  input.context?.token?.jwt ??
  null;

// Validação mínima de contexto + autenticação
const hasMinimumContext =
  Boolean(context.project_id) &&
  Boolean(context.chat_id) &&
  Boolean(jwt);

// ---------------------------------------------------------------------------
// 3️⃣ EXTRAÇÃO DA INTENÇÃO DA IA
// ---------------------------------------------------------------------------
const aiPayload =
  input.ai_response ??
  input.llm_output ??
  input.classification ??
  input.metadata ??
  input;

// Flags normalizadas
let shouldTransfer = false;
let targetStep = null;

// Intenção explícita
if (
  aiPayload?.action === "transfer_step" ||
  aiPayload?.should_transfer === true
) {
  shouldTransfer = true;
}

// Etapa alvo
targetStep =
  aiPayload?.target_step ??
  aiPayload?.next_step ??
  aiPayload?.step_target ??
  null;

// Sem etapa alvo, bloqueia
if (!targetStep) {
  shouldTransfer = false;
}

// ---------------------------------------------------------------------------
// 4️⃣ DECISÃO FINAL
// ---------------------------------------------------------------------------
const transferAllowed =
  hasMinimumContext &&
  shouldTransfer === true &&
  typeof targetStep === "string";

// ---------------------------------------------------------------------------
// 5️⃣ SAÍDA PADRONIZADA
// ---------------------------------------------------------------------------
return [
  {
    json: {
      // Contexto técnico
      context,

      // Autenticação
      auth: {
        jwt,
      },

      // Decisão de negócio
      transfer: {
        should_transfer: shouldTransfer,
        allowed: transferAllowed,
        target_step: targetStep,
      },

      // Debug e auditoria
      debug: {
        has_minimum_context: hasMinimumContext,
        jwt_present: Boolean(jwt),
        ai_payload_detected: aiPayload,
      },
    },
  },
];

const ctx = $json.context ?? {};
